function segmentDistance(p, a, b) {
  const dx = b.x - a.x, dy = b.y - a.y
  const t = clamp(((p.x - a.x) * dx + (p.y - a.y) * dy) / (dx * dx + dy * dy || 1), 0, 1)
  return Math.hypot(p.x - a.x - t * dx, p.y - a.y - t * dy)
}

function inSector(p, origin, dir, radius, angle, bodyRadius) {
  const dx = p.x - origin.x, dy = p.y - origin.y, d = Math.hypot(dx, dy)
  if (d <= bodyRadius) return true
  const half = angle * Math.PI / 360
  if ((dx * dir.x + dy * dir.y) / d >= Math.cos(half) && d <= radius + bodyRadius) return true
  return [-half, half].some(turn => {
    const x = dir.x * Math.cos(turn) - dir.y * Math.sin(turn)
    const y = dir.x * Math.sin(turn) + dir.y * Math.cos(turn)
    return segmentDistance(p, origin, { x: origin.x + x * radius, y: origin.y + y * radius }) <= bodyRadius
  })
}

function inPolygon(p, vertices, radius = 0) {
  let sign = 0, inside = true
  for (let i = 0; i < vertices.length; i++) {
    const a = vertices[i], b = vertices[(i + 1) % vertices.length]
    if (segmentDistance(p, a, b) <= radius) return true
    const cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x)
    if (Math.abs(cross) <= EPS) continue
    if (sign && Math.sign(cross) !== sign) inside = false
    sign = Math.sign(cross)
  }
  return inside
}

