function validWeaponState(s, legacy) {
  const w = s.weaponState
  const items = [...s.casts, ...s.projectiles, ...s.zones, ...(s.actions?.basic ? [s.actions.basic] : [])]
  if (!s.loadout.weapon) return w === undefined && items.every(item => item.weaponCastId === undefined)
  // Only declared skills emit friendly projectiles. A forged
  // source must not bypass cast accounting or borrow another skill's affixes.
  if (s.projectiles.some(p => !p.hostile && !['sj_yujian', ...SWORD_QI_SOURCES].includes(p.source))
    || s.zones.some(z => !z.hostile && !z.renderOnly
      && (!['shadow', 'formation', 'sancai', 'sword_rain', 'qinglian', 'jinghong'].includes(z.kind)
        || z.direct !== !['formation', 'sancai'].includes(z.kind)))) return false
  if (!object(w) || Object.keys(w).sort().join(',') !==
    'casts,effectiveCasts,entryMaxHp,focusCount,nextCastId,ringId'
    || w.ringId !== (s.loadout.ring?.id ?? null)
    || !uint(w.focusCount, 4) || !uint(w.effectiveCasts) || !uint(w.nextCastId) || w.nextCastId < 1
    || w.effectiveCasts >= w.nextCastId
    || w.focusCount !== ((s.training ? 0 : s.loadout.weaponFocusCount) + w.effectiveCasts) % 5
    || w.effectiveCasts > 0 && (!s.loadout.ring || ringDamageModifiers(s.loadout.ring).special <= 0)
    || w.entryMaxHp !== stats(s.base.xp, s.loadout, legacy).maxHp
    || !Array.isArray(w.casts) || w.casts.length > 20000) return false
  const receipts = new Map(), ordinals = new Set(), referenced = new Set()
  for (const c of w.casts) {
    if (!object(c) || Object.keys(c).sort().join(',') !== 'id,ordinal,procTargets,skillId'
      || !uint(c.id, w.nextCastId - 1) || c.id < 1 || receipts.has(c.id)
      || !DIRECT_CAST_SKILLS.includes(c.skillId)
      || !Array.isArray(c.procTargets) || c.procTargets.length > 20000 || new Set(c.procTargets).size !== c.procTargets.length
      || c.procTargets.some(id => typeof id !== 'string')
      || c.ordinal !== null && (!uint(c.ordinal, w.effectiveCasts) || c.ordinal < 1 || ordinals.has(c.ordinal))) return false
    receipts.set(c.id, c)
    if (c.ordinal !== null) ordinals.add(c.ordinal)
  }
  for (const item of items) {
    const source = item.formId === 'evo_wanjian' ? item.formId : item.skill ?? item.source ?? item.kind
    const skill = weaponSkill(source)
    const eligible = !item.hostile && !item.renderOnly && !continuousSource(source)
      && DIRECT_CAST_SKILLS.includes(skill)
    if (!eligible) {
      if (item.weaponCastId !== undefined) return false
      continue
    }
    const receipt = receipts.get(item.weaponCastId)
    if (!receipt || receipt.skillId !== skill
      || item.skill && !(item.pulseIndex > 0) && receipt.ordinal !== null) return false
    referenced.add(receipt.id)
  }
  return referenced.size === receipts.size
}

function validArmorState(s, legacy) {
  const a = s.armorState
  if (!s.loadout.armor) return a === undefined
  const rate = maximumRegenerationAmount(s.player.maxHp, s.loadout)
  return object(a) && validArmorEffectState(s)
    && a.armorId === s.loadout.armor.id && finite(a.healedTotal) && a.healedTotal >= 0
    && a.healedTotal <= rate * Math.floor(s.ticks / 180) + EPS
}

const castContext = s => ({ loadout: copy(s.loadout), xp: s.player.xp })
function validCastContext(context, s) {
  return object(context) && validLoadout(context.loadout, context.xp) && uint(context.xp, s.player.xp)
    && sameWeapon(context.loadout, s.loadout)
    && (context.weaponAttack === undefined ? !context.loadout.weapon || context.loadout.weaponEquipped === false : context.loadout.weapon
      && finite(context.weaponAttack) && context.weaponAttack >= weaponAttackRange(context.loadout.weapon).min
      && context.weaponAttack <= weaponAttackRange(context.loadout.weapon).max)
    && (context.weaponMagicAttack === undefined ? !context.loadout.weapon || context.loadout.weaponEquipped === false : context.loadout.weapon
      && finite(context.weaponMagicAttack) && context.weaponMagicAttack >= weaponMagicAttackRange(context.loadout.weapon).min
      && context.weaponMagicAttack <= weaponMagicAttackRange(context.loadout.weapon).max)
}
function castAttack(context) {
  const attack = stats(context.xp, context.loadout).attack
  return context.weaponAttack === undefined || context.loadout.weaponEquipped === false ? attack
    : attack - weaponFlatAttack(context.loadout.weapon) + context.weaponAttack
}
function castMagicAttack(context) {
  const attack = stats(context.xp, context.loadout).magicAttack
  return context.weaponMagicAttack === undefined || context.loadout.weaponEquipped === false ? attack
    : attack - weaponFlatMagicAttack(context.loadout.weapon) + context.weaponMagicAttack
}

function validFormCast(c, time) {
  if (c.formId === undefined) return c.castContext?.loadout?.growthVersion !== 1
    && c.pulseCount === undefined && c.pulseIndex === undefined
  const loadout = c.castContext?.loadout
  if (loadout?.growthVersion !== 1) return false
  const rain = c.formId === 'evo_wanjian'
  if (rain && (c.skill !== 'sj_yujian' || !loadout.evolutions.includes(c.formId))) return false
  const form = rain ? skillForm(c.formId, loadout.evolutionLevels[c.formId], c.level) : formFor(c.skill, c.level, loadout)
  const timing = castActionTiming(form.id, form.hits ?? 1, equipmentCastSpeed(loadout,c.castContext.xp))
  return c.formId === form.id && c.pulseCount === (form.hits ?? 1)
    && uint(c.pulseIndex, timing.releases.length - 1) && finite(c.startedAt) && c.startedAt <= time
    && Math.abs(Math.hypot(c.dirX, c.dirY) - 1) <= EPS
    && Math.abs(c.releaseAt - (c.startedAt + timing.releases[c.pulseIndex])) <= EPS
    && finite(c.lockAt) && Math.abs(c.lockAt - c.startedAt - timing.lock) <= EPS
    && c.locked === (time + EPS >= c.lockAt)
    && (c.skill !== 'sj_yujian' || rain || uint(c.swordCount, Math.min(10,c.level)) && c.swordCount > 0)
    && (form.id !== 'evo_tiandi' || typeof c.windupEffectId === 'string')
}

function validFormZone(z) {
  if (z.formId === undefined) return z.castContext?.loadout?.growthVersion !== 1
    && z.pulseCount === undefined && z.pulseIndex === undefined
  const parents = { shadow: 'sj_shadow', formation: 'sj_formation', sancai: 'sj_sancai', sword_rain: 'sj_yujian', qinglian: 'sj_qinglian', jinghong: 'sj_jinghong' }
  const parent = parents[z.kind], loadout = z.castContext?.loadout
  if (!parent || loadout?.growthVersion !== 1 || z.parentLevel !== loadout.active[parent]) return false
  const special = z.kind === 'sword_rain'
  const form = special ? skillForm('evo_wanjian', loadout.evolutionLevels.evo_wanjian, z.parentLevel)
    : formFor(parent, z.parentLevel, loadout)
  if (special && !loadout.evolutions.includes('evo_wanjian')) return false
  const level = loadout.evolutionLevels[form.id] ?? z.parentLevel
  const base = castAttack(z.castContext) * levelValue(parent, 'damage', z.parentLevel, loadout)
  const total = special ? base * convergenceRainMultiplier(level)
    : parent === 'sj_formation' ? base * GS.sj_formation.ticks
      * (form.id === 'evo_sixiang' ? GEVO.evo_sixiang.budgetMultipliers[level - 1] * GEVO.evo_sixiang.cooldown / GS.sj_formation.cooldown : 1) : base
  return z.formId === form.id && z.source === form.id && z.formLevel === level
    && z.shape === form.shape && z.hits === form.hits && z.pulseCount === form.hits
    && uint(z.pulseIndex, form.hits) && z.ticks + z.pulseIndex === form.hits
    && ['radius', 'reach', 'width', 'angle', 'eyes', 'targetCap', 'interval'].every(key => z[key] === form[key])
    && finite(z.startedAt) && finite(z.dirX) && finite(z.dirY)
    && Math.abs(Math.hypot(z.dirX, z.dirY) - 1) <= EPS
    // A qinglian zone stores the whole cast budget; its hits split it by ring share.
    && Math.abs(z.damage - (parent === 'sj_qinglian' ? total : total / form.hits)) <= EPS
    && Math.abs(z.nextAt - (z.startedAt + form.initialDelay + z.pulseIndex * form.interval)) <= EPS
    && Math.abs(z.expiresAt - (z.startedAt + form.duration + (parent === 'sj_sancai' || parent === 'sj_qinglian' ? 0 : .2))) <= EPS
    && (parent !== 'sj_sancai' || !z.hostile && z.direct === false)
    && z.phase === (z.pulseIndex ? 'active' : 'windup')
    && (!special || finite(z.originX) && finite(z.originY))
    && (parent !== 'sj_jinghong' || typeof z.targetId === 'string' && z.direct === true)
}

// Piercing receipts outlive temporary actors. The allocation ledger retains
// their exact identities without returning a consumed target slot after death.
function validSwordHitId(id, s) {
  return typeof id === 'string' && (plan(s).some(p => p.id === id)
    || (s.monsterMechanics?.summons || []).some(entry => entry.id === id))
}

function validSwordQi(shot, s) {
  if (!SWORD_QI_SOURCES.includes(shot.source)) return shot.bladeKind === undefined
  if (shot.hostile || shot.castContext?.loadout?.growthVersion !== 1) return false
  const level = shot.castContext.loadout.active[shot.source]
  if (!level) return false
  const form = skillForm(shot.source, level)
  if (!['crescent-projectile', 'cross-projectile'].includes(form.shape)) return false
  if (shot.shape !== form.shape || shot.bladeKind !== form.bladeKind || shot.width !== form.width
    || shot.bladeWidth !== form.bladeWidth || shot.radius !== form.bladeWidth / 2
    || shot.targetCap !== form.targetCap || shot.speed !== form.speed
    || !uint(shot.pulseIndex, form.hits) || shot.pulseIndex < 1 || shot.pulseCount !== form.hits
    || !['dirX','dirY','originX','originY','travelled','range','startedAt'].every(k=>finite(shot[k]))
    || Math.abs(Math.hypot(shot.dirX,shot.dirY)-1)>EPS
    || Math.abs(shot.vx-shot.dirX*form.speed)>EPS || Math.abs(shot.vy-shot.dirY*form.speed)>EPS
    || shot.range <= EPS || shot.range > form.reach
    || shot.travelled < 0 || shot.travelled > shot.range + EPS
    || shot.startedAt < 0 || shot.startedAt > s.time
    || Math.abs(shot.x-shot.originX-shot.dirX*shot.travelled)>1e-6
    || Math.abs(shot.y-shot.originY-shot.dirY*shot.travelled)>1e-6
    || shot.hitIds.length > form.targetCap || new Set(shot.hitIds).size !== shot.hitIds.length
    || shot.hitIds.some(id=>!validSwordHitId(id,s))) return false
  const range = swordQiTravelLimit(form.bladeKind,form.width,form.bladeWidth,
    {x:shot.originX,y:shot.originY},shot.dirX,shot.dirY,form.reach,s.arenaVersion,swordQiPoseIndex(shot))
  if (Math.abs(range-shot.range)>1e-6) return false
  const expected = castAttack(shot.castContext)
    * levelValue(shot.source,'damage',level,shot.castContext.loadout)
    * skillHitShare(shot.source,level,shot.pulseIndex)
  if (Math.abs(shot.damage-expected)>EPS) return false
  if (shot.dissolveAt === null) return shot.travelled < shot.range
    && Math.abs(shot.expiresAt-(shot.startedAt+shot.range/form.speed+SWORD_QI_TAIL))<EPS
  return finite(shot.dissolveAt) && shot.dissolveAt >= shot.startedAt && shot.dissolveAt <= s.time
    && Math.abs(shot.travelled-shot.range)<EPS
    && Math.abs(shot.expiresAt-shot.dissolveAt-SWORD_QI_TAIL)<EPS
}

function validYujianRuntime(shot,s) {
  if(shot.yujianSlot===undefined)return true
  if(!validYujianShot(shot))return false
  const loadout=shot.castContext?.loadout,level=loadout?.active?.sj_yujian
  if(loadout?.growthVersion!==1 || !Number.isInteger(level) || level<1 || level>11
    || shot.yujianSlot>=10 || !Number.isInteger(shot.pulseIndex)
    || shot.pulseIndex<1 || shot.pulseIndex>Math.min(10,level) || shot.radius!==7
    || shot.gatherAt>s.time || Math.abs(shot.startedAt-shot.gatherAt)>EPS
    || Math.abs(shot.flightAt-shot.gatherAt)>EPS
    || shot.hitIds.length>1 || shot.hitIds.some(id=>id!==shot.targetId)
    || shot.trail.some(p=>p.at<shot.gatherAt || p.at>s.time))return false
  const expected=castAttack(shot.castContext)*levelValue('sj_yujian','damage',level,loadout)
    *levelValue('sj_yujian','sword_damage_share',level,loadout)
  if(Math.abs(shot.damage-expected)>EPS)return false
  if(shot.dissolveAt!==null)return shot.dissolveAt>=shot.gatherAt && shot.dissolveAt<=s.time
    && Math.abs(shot.expiresAt-shot.dissolveAt-YUJIAN_TAIL)<EPS
  const spirit=loadout.passive.sj_spirit||0
  const reach=skillForm('sj_yujian',level).reach*(1+(spirit?levelValue('sj_spirit','reach_bonus',spirit,loadout):0))
  return shot.hitIds.length===0 && Math.abs(shot.expiresAt-shot.flightAt-reach/680-1)<EPS
}

function readyNewSkills(s) {
  for (const id of Object.keys(s.loadout.active)) {
    if (s.cooldowns[id] === undefined) s.cooldowns[id] = 0
  }
  if (s.loadout.evolutions.includes('evo_wanjian') && s.cooldowns.evo_wanjian === undefined) {
    s.cooldowns.evo_wanjian = 0
  }
}

// All required units are registered up front, including dormant boss support.
// These immutable plans contain no random choices and are reconstructed on load.
const PLANS = FLOORS.map(f => f.waves.map(w => {
  if (f.floor === 1) return FLOOR01.waves[w.wave - 1].batches.flatMap(b =>
    b.unit_ids.map((id, i) => ({ localId: id, archetype: b.archetype, portal: b.portal,
      at: b.at_s + i * b.emit_step_s, trigger: b.trigger === 'wave_start' ? 'start' : 'half',
      warning: b.warning_s })))
  const groups = [...w.enemy_groups].sort((a, b) =>
    Number(A[b.archetype].role === 'boss') - Number(A[a.archetype].role === 'boss'))
  let index = 0, normalIndex = 0
  return groups.flatMap(g => Array.from({ length: g.count }, () => {
    const i = index++, normal = A[g.archetype].role === 'normal'
    const trigger = w.kind === 'boss' && normal && normalIndex++ >= 4 ? 'half' : 'start'
    return { localId: `u${i + 1}`, archetype: g.archetype,
      portal: PORTALS[(w.wave + i * 3) % PORTALS.length].id, at: i * .22,
      trigger, warning: normal ? .9 : 1.2 }
  }))
}))

function plan(state, wave = state.wave) {
  return PLANS[state.floor - 1][wave - 1].map(p => ({
    ...p, id: `a${state.attemptId}:f${state.floor}:w${wave}:${p.localId}`,
  }))
}

function coreRankFor(state, kill, drops) {
  if (state.training) return 0
  const prefix = `a${state.attemptId}:f${state.floor}:w${kill.wave}:`
  return drops[`${kill.wave}:${kill.id.slice(prefix.length)}`] || 0
}

// Legacy graded receipts retained for validated replay compatibility. Economy v2
// converts these opaque units into spirit stones; these are NOT demon-core XP.
// Completion awards are accounted for separately.
export function coreLootSummary(snapshot) {
  if (!snapshot.loot) return null
  const byRank = Array(7).fill(0)
  for (const kill of snapshot.killLedger) {
    if (kill.coreRank > 0) byRank[kill.coreRank - 1]++
  }
  return {
    byRank, count: byRank.reduce((sum, count) => sum + count, 0),
    value: byRank.reduce((sum, count, i) => sum + count * CORE_RANK_VALUES[i + 1], 0),
  }
}

function jsonSafe(value, seen = new Set(), depth = 0) {
  if (depth > 30) return false
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return true
  if (typeof value === 'number') return finite(value)
  if (typeof value !== 'object' || seen.has(value)) return false
  seen.add(value)
  const ok = Object.values(value).every(v => jsonSafe(v, seen, depth + 1))
  seen.delete(value)
  return ok
}

function positioned(v) {
  return object(v) && typeof v.id === 'string' && finite(v.x) && finite(v.y)
    && finite(v.radius) && v.radius >= 0
}

function validView(view) {
  return view === null || object(view) && ['xmin', 'xmax', 'ymin', 'ymax'].every(k => finite(view[k]))
    && view.xmin < view.xmax && view.ymin < view.ymax
    && (!('followPlayer' in view) || typeof view.followPlayer === 'boolean')
}

function validAI(ai, time) {
  if (!object(ai) || !['approach', 'windup', 'active', 'recovery'].includes(ai.mode)
    || !['readyAt', 'graceUntil', 'until', 'entryUntil', 'transitionUntil', 'eligibleSince',
      'faceX', 'faceY', 'offset'].every(k => finite(ai[k]))
    || !uint(ai.sequence) || ![1, 2].includes(ai.phase) || ![-1, 1].includes(ai.orbitSign)
    || typeof ai.transitionPending !== 'boolean' || !object(ai.cooldowns)
    || !Object.values(ai.cooldowns).every(t => finite(t) && t >= 0)) return false
  if (ai.mode === 'approach') return ai.attack === null
  const a = ai.attack
  return object(a) && typeof a.id === 'string' && ['bite', 'gore', 'charge', 'shot', 'stone', 'web', 'slam', 'sweep'].includes(a.kind)
    && ['circle', 'sector', 'capsule'].includes(a.shape) && validElement(a) && validIncomingType(a)
    && (a.emissionFaceX===undefined || a.kind==='shot' && [-1,1].includes(a.emissionFaceX))
    && ['damage', 'windup', 'range', 'active', 'recovery', 'cooldown', 'lock', 'speed',
      'radius', 'width', 'angle', 'travelled', 'maxRange'].every(k => finite(a[k]) && a[k] >= 0)
    && ['x', 'y', 'targetX', 'targetY', 'dirX', 'dirY', 'startedAt'].every(k => finite(a[k]))
    && Math.abs(Math.hypot(a.dirX, a.dirY) - 1) <= EPS && a.startedAt <= time
    && ['locked', 'hit', 'fired', 'boundary', 'clipped'].every(k => typeof a[k] === 'boolean')
    && uint(a.segments, 2) && a.segments >= 1 && uint(a.segment, a.segments) && a.segment >= 1
    && [1, 2].includes(a.cost)
}

/**
 * Structural AND reward-ledger validation. This detects corrupt/non-finite state
 * and inconsistent earnings; it is not a signature against a malicious host.
 */
export function validateTowerSnapshot(s, legacy = false) {
  try {
    if (!object(s) || !jsonSafe(s) || s.schema !== 1 || !PHASES.includes(s.phase)
      || !isPlayableClass(s.loadout?.classId)
      || !uint(s.attemptId) || (!s.training && s.attemptId < 1)
      || typeof s.training !== 'boolean' || !uint(s.floor, 9) || s.floor < 1
      || !uint(s.wave, 20) || s.wave < 1 || !uint(s.ticks) || s.time !== s.ticks / 60
      || !finite(s.remainder) || s.remainder < 0 || s.remainder >= STEP + EPS
      || !uint(s.rng, 0xffffffff) || !s.rng || !uint(s.nextId)
      || !validLoadout(s.loadout, s.player?.xp) || !object(s.player) || !object(s.base)
      || !uint(s.base.xp, TOWER_XP_CAP) || !uint(s.base.normalCoreCounter, 19)
      || !finite(s.base.hp) || s.base.hp <= 0 || s.base.hp > stats(s.base.xp, s.loadout, legacy).maxHp
      || !uint(s.player.xp, TOWER_XP_CAP) || !finite(s.player.hp) || s.player.hp < 0
      || !finite(s.player.x) || !finite(s.player.y) || !finite(s.player.faceX) || !finite(s.player.faceY)
      || !object(s.input) || !finite(s.input.x) || !finite(s.input.y)
      || Math.hypot(s.input.x, s.input.y) > 1 + EPS
      || !uint(s.normalCoreCounter, 19) || !uint(s.waveKilled) || !uint(s.wavePlanned)
      || !object(s.cooldowns) || !Object.values(s.cooldowns).every(v => finite(v) && v >= 0)
      || (s.orbitUntil !== undefined && (!finite(s.orbitUntil) || s.orbitUntil < 0
        || s.orbitUntil > s.time + GS.sj_wanjian.duration + EPS))
      || (s.orbitClock !== undefined && (!finite(s.orbitClock) || s.orbitClock < 0))
      || (s.orbitPace !== undefined && (!finite(s.orbitPace) || s.orbitPace < 0 || s.orbitPace > 4))
      || !finite(s.waveStartedAt) || s.waveStartedAt > s.time
      || !finite(s.hurtUntil) || !finite(s.nextWindupAt) || !finite(s.supportAt)
      || typeof s.supportReleased !== 'boolean' || !finite(s.gateReadyAt)
      || !uint(s.rawKillXp) || !object(s.earned)) return false
    if (!validateBreakthrough(s)) return false
    if (!validView(s.view) || !finite(s.trainingResetAt) || !validYujianState(s.yujian,s.time)
      || s.yujian?.head>=10
      || (s.loadout?.growthVersion===1 && (!s.yujian || s.yujian.nextAt>s.time+yujianGenerationInterval(s.loadout)+EPS))
      || ('arenaVersion' in s && s.arenaVersion !== 1)
      || Object.keys(s.earned).sort().join(',') !== 'contribution,cores,xp'
      || !Object.values(s.earned).every(v => uint(v))) return false
    if (s.loot !== undefined && (!object(s.loot)
      || Object.keys(s.loot).sort().join(',') !== 'seed,version'
      || s.loot.version !== 1 || !uint(s.loot.seed, 0xffffffff))) return false
    const coreDrops = s.loot ? buildCoreDropPlan(s.floor, s.loot.seed) : null
    for (const key of ['enemies', 'projectiles', 'zones', 'drops', 'effects', 'pending',
      'reserved', 'casts', 'killLedger', 'clearedWaves', 'gateEntries']) {
      if (!Array.isArray(s[key]) || s[key].length > 20000) return false
    }
    if (!validQingping(s) || !validSwordBursts(s) || !validWeaponBleeds(s)) return false
    if (!validWeaponState(s, legacy) || !validArmorState(s, legacy) || !validateMonsterMechanics(s)) return false
    if ((s.loadout.weapon || s.loadout.growthVersion === 1) && !validAttackActions(s.actions, s.time, c => validCastContext(c, s))) return false
    if (s.actions) {
      const bodyEnds = s.casts.map(c => {
        if (!c.formId) return c.releaseAt
        const form = c.formId === 'evo_wanjian'
          ? skillForm(c.formId, c.castContext.loadout.evolutionLevels[c.formId], c.level)
          : formFor(c.skill, c.level, c.castContext.loadout)
        return c.startedAt + castActionTiming(form.id, form.hits ?? 1, equipmentCastSpeed(c.castContext.loadout,c.castContext.xp)).duration
      })
      if (bodyEnds.some(end => end > s.time + EPS && s.actions.busyUntil + EPS < end)) return false
      if (s.actions.current) {
        const c = s.actions.current, timing = castActionTiming(c.skill, c.hits, c.speed)
        if (Math.abs(c.endsAt - c.startedAt - timing.duration) > EPS
          || Math.abs(c.releaseAt - c.startedAt - timing.windup) > EPS
          || (!validCastContext(c.castContext, s) || c.speed !== equipmentCastSpeed(c.castContext.loadout,c.castContext.xp)) || !GS[c.parent]) return false
      }
      const b = s.actions.basic
      if (b) {
        const profile = equipmentAttackProfile(b.castContext.loadout)
        if (Math.abs(b.endsAt - b.startedAt - profile.duration) > EPS
          || Math.abs(b.releaseAt - b.startedAt - profile.duration / 2) > EPS
          || Math.abs(s.actions.readyAt - b.startedAt - profile.interval) > EPS
          || bodyEnds.some(end => end > b.startedAt + EPS)) return false
      }
    }
    if (s.monsterControl !== undefined && (!object(s.monsterControl)
      || Object.keys(s.monsterControl).sort().join(',') !== 'immuneUntil,rootUntil,slowFraction,slowUntil'
      || !Object.values(s.monsterControl).every(v => finite(v) && v >= 0)
      || s.monsterControl.slowFraction > .3)) return false
    const growth = s.loadout.growthVersion === 1
    if (growth && (!uint(s.base.tutorialWaves, 3)
      || s.loadout.tutorialWaves !== tutorialProgress(s.base.tutorialWaves, s.floor, s.training ? [] : s.clearedWaves))) return false
    const validContext = item => growth
      ? validCastContext(item.castContext, s) : item.castContext === undefined
    const expectedStats = stats(s.player.xp, s.loadout, legacy)
    if (!finite(s.base.mana) || s.base.mana < 0 || s.base.mana > stats(s.base.xp,s.loadout,legacy).maxMana
      || !finite(s.player.mana) || s.player.mana < 0 || s.player.mana > expectedStats.maxMana + EPS
      || !object(s.manaState) || Object.keys(s.manaState).sort().join(',') !== 'recovered,spent'
      || !finite(s.manaState.spent) || s.manaState.spent < 0 || !finite(s.manaState.recovered) || s.manaState.recovered < 0
      || !validSpiritState(s)
      || s.manaState.recovered > expectedStats.manaRegen*SPIRIT_RULES.peacefulMultiplier*s.time+s.spiritState.pillRecovered + 1e-7
      || Math.abs(s.base.mana + s.manaState.recovered - s.manaState.spent - s.player.mana) > 1e-7) return false
    if (Object.entries(expectedStats).some(([k, v]) => !finite(s.player[k]) || Math.abs(s.player[k] - v) > EPS)
      || s.player.hp > expectedStats.maxHp || s.player.radius !== 18
      || (s.phase === 'lost' ? s.player.hp !== 0 : s.player.hp <= 0)
      || (s.arenaVersion === 1 ? !insideHex(s.player, s.player.radius)
        : s.player.x < -894 || s.player.x > 960 || s.player.y < -1122 || s.player.y > 1002)) return false
    if (Object.keys(s.loadout.active).some(id => !finite(s.cooldowns[id]))) return false
    if (s.loadout.evolutions.includes('evo_wanjian') && !finite(s.cooldowns.evo_wanjian)) return false
    const currentPlan = plan(s), lookup = new Map(currentPlan.map(p => [p.id, p]))
    const allIds = new Set(), deadNow = []
    let xp = 0, normal = 0, cores = 0
    for (const kill of s.killLedger) {
      if (!object(kill) || !uint(kill.wave, s.wave) || kill.wave < 1 || allIds.has(kill.id)) return false
      const authored = plan(s, kill.wave).find(p => p.id === kill.id)
      if (!authored || authored.archetype !== kill.archetype) return false
      allIds.add(kill.id)
      const a = A[kill.archetype]
      xp += towerKillXp(s.floor, kill.wave, authored.localId)
      if (coreDrops) {
        const coreRank = coreRankFor(s, kill, coreDrops)
        if (kill.coreRank !== coreRank || coreRank && coreRank !== a.rank) return false
        cores += CORE_RANK_VALUES[coreRank]
      } else {
        if (kill.coreRank !== undefined) return false
        if (a.role === 'normal') normal++
        else cores += (a.role === 'elite' ? ELITE_CORE : BOSS_CORE)[a.rank]
      }
      if (kill.wave === s.wave) deadNow.push(kill.id)
    }
    for (const kind of ['pending', 'reserved', 'enemies']) {
      for (const item of s[kind]) {
        if (kind === 'enemies' && item.temporary) {
          if (allIds.has(item.id) || lookup.has(item.id) || !positioned(item)
            || !A[item.archetype] || !validMonsterAttributes(item,A[item.archetype],s.floor,s.time)
            || !validAI(item.ai, s.time) || s.arenaVersion === 1 && !insideHex(item, item.radius)) return false
          allIds.add(item.id)
          continue
        }
        const p = lookup.get(item.id)
        if (!p || p.archetype !== item.archetype || allIds.has(item.id)) return false
        allIds.add(item.id)
        if (kind !== 'enemies') {
          if (item.portal !== p.portal || item.at !== p.at || item.trigger !== p.trigger
            || item.warning !== p.warning || !finite(item.retryAt) || !finite(item.waitingSince)) return false
          if (kind === 'reserved' && (!positioned(item) || !finite(item.readyAt)
            || s.arenaVersion === 1 && (item.radius !== radiusOf(item.archetype)
              || !insideHex(item, item.radius)))) return false
        } else {
          const authored = towerEnemyStats(A[item.archetype], s.floor, s.wave)
          if (!positioned(item) || item.family !== familyOf(item.archetype) || item.role !== A[item.archetype].role
            || !validMonsterAttributes(item,A[item.archetype],s.floor,s.time)
            || item.maxHp !== authored.hp || !finite(item.hp) || item.hp <= 0 || item.hp > item.maxHp
            || item.rank !== A[item.archetype].rank || item.damage !== authored.damage
            || item.moveSpeed !== authored.moveSpeed || item.radius !== radiusOf(item.archetype)
            || s.arenaVersion === 1 && !insideHex(item, item.radius)
            || !validAI(item.ai, s.time) || !finite(item.woundBudget) || item.woundBudget < 0
            || !finite(item.woundUntil) || !finite(item.orbitNextAt)) return false
        }
      }
    }
    if (s.wavePlanned !== currentPlan.length || s.waveKilled !== deadNow.length
      || s.pending.length + s.reserved.length + s.enemies.filter(e => !e.temporary).length + deadNow.length !== currentPlan.length
      || s.enemies.filter(e => !e.temporary).length + s.reserved.length > FLOORS[s.floor - 1].concurrent_cap) return false
    const clearedCount = s.phase === 'won' ? 20 : s.wave - 1
    if (s.training) {
      if (s.phase === 'won' || s.clearedWaves.length || s.player.xp !== s.base.xp
        || s.normalCoreCounter !== s.base.normalCoreCounter
        || Object.values(s.earned).some(v => v !== 0)) return false
    } else {
      if (s.clearedWaves.length !== clearedCount
        || s.clearedWaves.some((w, i) => w !== i + 1)) return false
      for (const w of s.clearedWaves) {
        if (s.killLedger.filter(k => k.wave === w).length !== PLANS[s.floor - 1][w - 1].length) return false
      }
      if (!coreDrops) cores += Math.floor((s.base.normalCoreCounter + normal) / 20)
      let contribution = 0
      for (const w of s.clearedWaves) {
        const kind = FLOORS[s.floor - 1].waves[w - 1].kind
        // Point vouchers are granted only by campaign first-clear settlement.
        if (kind === 'boss') cores += 5 * (s.floor - 1)
      }
      if (s.earned.cores !== cores || s.earned.contribution !== contribution
        || s.earned.xp !== (s.breakthrough ? breakthroughXp(s)?.earned : Math.min(cultivationXpCap(s.base.xp) - s.base.xp, xp))
        || s.player.xp !== s.base.xp + s.earned.xp + (s.breakthrough?.events.length || 0)
        || s.normalCoreCounter !== (coreDrops ? s.base.normalCoreCounter
          : (s.base.normalCoreCounter + normal) % 20)) return false
    }
    if (s.rawKillXp !== xp) return false
    if (!s.projectiles.every(p => positioned(p) && finite(p.vx) && finite(p.vy) && validElement(p) && validIncomingType(p) && validProjectileLaunch(p)
      && finite(p.damage) && p.damage >= 0 && finite(p.expiresAt) && typeof p.hostile === 'boolean'
      && Array.isArray(p.hitIds) && validSwordQi(p, s) && validYujianRuntime(p,s)
      && (p.hostile ? p.castContext === undefined : validContext(p)))) return false
    // Slot indices identify hover origins; later generations may reuse them in flight.
    const swordIds=s.projectiles.filter(p=>p.yujianSlot!==undefined).map(p=>`${p.gatherAt}:${p.yujianSlot}`)
    if(new Set(swordIds).size!==swordIds.length)return false
    if(s.yujian && s.yujian.ready>Math.min(10,s.loadout.active.sj_yujian||0))return false
    if (!s.zones.every(z => {
      if (!positioned(z) || !finite(z.expiresAt) || !validIncomingType(z) || typeof z.hostile !== 'boolean'
        || typeof z.renderOnly !== 'boolean' || !['windup', 'active'].includes(z.phase)) return false
      if (z.renderOnly) return ['enemy_windup', 'enemy_attack'].includes(z.kind)
        && s.enemies.some(e => e.id === z.ownerId && e.ai.attack?.id === z.attackId)
        && ['toX', 'toY', 'width', 'angle', 'faceX', 'faceY'].every(k => finite(z[k]))
        && typeof z.locked === 'boolean' && ['circle', 'capsule', 'sector'].includes(z.shape)
      return ['shadow', 'formation', 'sancai', 'sword_rain', 'qinglian', 'jinghong', 'web', 'stone'].includes(z.kind)
        && finite(z.damage) && z.damage >= 0 && finite(z.nextAt) && finite(z.interval) && z.interval > 0
        // Authored zones are checked against their exact form by validFormZone.
        // Keep the legacy bound only for zones without a form (rank2 rain has 25 pulses).
        && uint(z.ticks, z.pulseCount ?? 6)
        && uint(z.pulseCount ?? 6, z.formId === undefined ? 24 : Number.MAX_SAFE_INTEGER) && validFormZone(z)
        && (z.kind === 'qinglian' ? z.targetCap === null : uint(z.targetCap, 8) && z.targetCap >= 1)
        && typeof z.direct === 'boolean'
        && (z.hostile ? z.castContext === undefined : validContext(z))
    })) return false
    if (!validPickups(s)) return false
    if (!s.drops.every(d => {
      if (s.pickups && ['core','material'].includes(d.kind)) return true
      if (!positioned(d) || !finite(d.expiresAt) || !finite(d.amount)) return false
      if (d.kind !== 'core') return ['heal', 'resource'].includes(d.kind)
      return !!coreDrops && !s.training && uint(d.rank, 7) && d.rank > 0
        && d.amount === CORE_RANK_VALUES[d.rank]
        && s.killLedger.some(k => k.id === d.killId && k.coreRank === d.rank)
    })) return false
    const coreIds = s.drops.filter(d => d.kind === 'core').map(d => d.killId)
    if (!s.pickups && new Set(coreIds).size !== coreIds.length) return false
    if (!s.effects.every(e => positioned(e) && finite(e.expiresAt))) return false
    if (!s.casts.every(c => validContext(c) && (growth ? GS : S)[c.skill]?.kind === 'active'
      && c.level === (growth ? c.castContext.loadout : s.loadout).active[c.skill]
      && ['releaseAt', 'x', 'y', 'dirX', 'dirY', 'targetX', 'targetY'].every(k => finite(c[k]))
      && validFormCast(c, s.time))) return false
    return s.gateEntries.every(e => object(e) && finite(e.amount) && e.amount >= 0 && finite(e.expiresAt))
  } catch { return false }
}

// Called only after a schema-1 campaign passes checksum AND legacy validation.
export function migrateTowerCultivation(snapshot) {
  if (!validateTowerSnapshot(snapshot, true)) throw new TypeError('Invalid legacy tower snapshot')
  const next = copy(snapshot)
  next.base.hp = Math.min(next.base.hp, stats(next.base.xp, next.loadout).maxHp)
  Object.assign(next.player, stats(next.player.xp, next.loadout))
  next.player.hp = Math.min(next.player.hp, next.player.maxHp)
  if (!validateTowerSnapshot(next)) throw new TypeError('Invalid migrated tower snapshot')
  return next
}

// Campaign must verify its checksum first. Schema-1 cultivation migration runs
// before this function; no invalid legacy ledger can be repaired by conversion.
// loadout.tutorialWaves is the post-migration awarded teaching stage.
// Infer the lowest valid entry stage from the authored floor milestones.
export function migrateTowerGrowth(snapshot, loadout) {
  loadout = {...loadout, classId: loadout?.classId === undefined ? snapshot?.loadout?.classId : loadout.classId}
  if (!validateTowerSnapshot(snapshot) || snapshot.loadout.growthVersion !== undefined
    || !validLoadout(loadout, snapshot.player.xp) || loadout.growthVersion !== 1
    || !sameWeapon(snapshot.loadout, loadout)) throw new TypeError('Invalid legacy growth migration')
  const next = copy(snapshot), context = castContext(snapshot)
  for (const item of [...next.casts, ...next.projectiles.filter(p => !p.hostile),
    ...next.zones.filter(z => !z.hostile && !z.renderOnly)]) item.castContext = copy(context)
  next.loadout = copy(loadout)
  next.yujian = newYujianState(next.player,next.time,next.loadout)
  next.actions = newAttackActions()
  next.actions.busyUntil = Math.max(next.time, ...next.casts.map(c => c.releaseAt))
  const earnedTutorial = tutorialProgress(0, next.floor, next.training ? [] : next.clearedWaves)
  if (loadout.tutorialWaves < earnedTutorial) throw new TypeError('Invalid migrated teaching stage')
  next.base.tutorialWaves = loadout.tutorialWaves === earnedTutorial ? 0 : loadout.tutorialWaves
  readyNewSkills(next)
  Object.assign(next.player, stats(next.player.xp, next.loadout))
  if (!validateTowerSnapshot(next)) throw new TypeError('Invalid migrated growth snapshot')
  return next
}

export class TowerRun {
  constructor({ attemptId, floor, seed = 1, hp, xp, normalCoreCounter = 0, loadout,
    mana, spiritPills = 0, training = false, lootVersion = 1, arenaVersion = 0, forgePity = {fa:0,bao:0,ling:0} }) {
    loadout = {...loadout, classId: loadout?.classId === undefined ? DEFAULT_CLASS_ID : loadout.classId}
    loadout=applyEquipmentSkillLevels(loadout)
    if (!uint(attemptId) || (!training && attemptId < 1) || !uint(floor, 9) || floor < 1
      || !uint(seed, 0xffffffff) || !uint(xp, TOWER_XP_CAP) || !validLoadout(loadout, xp)
      || !finite(hp) || hp <= 0 || hp > stats(xp, loadout).maxHp
      || !uint(normalCoreCounter, 19) || typeof training !== 'boolean'
      || ![0, 1].includes(lootVersion) || ![0, 1].includes(arenaVersion)) throw new RangeError('Invalid tower attempt')
    mana = mana ?? stats(xp, loadout).maxMana
    if (!finite(mana) || mana < 0 || mana > stats(xp, loadout).maxMana || !uint(spiritPills,2000000000)) throw new RangeError('Invalid mana')
    const chosen = copy(loadout)
    this._playtestAssist = false
    this.state = {
      breakthrough: freshBreakthrough(),
      schema: 1, attemptId, floor, phase: 'playing', training, time: 0, ticks: 0, remainder: 0,
      wave: 1, waveStartedAt: 0, waveKilled: 0, wavePlanned: 0, nextId: 1,
      player: { x: 33, y: -60, hp, xp, mana, ...stats(xp, chosen), radius: 18, faceX: 1, faceY: 0 },
      enemies: [], projectiles: [], zones: [], drops: [], effects: [], pending: [], reserved: [],
      earned: { xp: 0, cores: 0, contribution: 0 }, rawKillXp: 0,
      normalCoreCounter, loadout: chosen, rng: seed || 0x6d2b79f5,
      base: { xp, hp, mana, normalCoreCounter }, manaState: {spent:0,recovered:0}, input: { x: 0, y: 0 },
      spiritState: freshSpiritState(spiritPills),
      cooldowns: Object.fromEntries(Object.keys(chosen.active).map(id => [id, 0])),
      casts: [], killLedger: [], clearedWaves: [], gateEntries: [], gateReadyAt: 0, scarReadyAt: 0,
      hurtUntil: 0, nextWindupAt: 0, supportReleased: false, supportAt: -1,
      view: null, trainingResetAt: 0,
      monsterMechanics: { version: 1, zones: [], summons: [], sequence: 0, nextMajorAt: 0 },
      monsterControl: { rootUntil: 0, immuneUntil: 0, slowUntil: 0, slowFraction: 0 },
    }
    // Shape is opt-in per attempt. Historical snapshots stay rectangular.
    if (arenaVersion === 1) this.state.arenaVersion = 1
    // A retry gets a fresh allocation; combat randomness and kill order cannot
    // move its drops. An old snapshot without this field continues its old rule.
    if (lootVersion === 1) this.state.loot = {
      version: 1, seed: (seed ^ Math.imul(attemptId >>> 0, 0x9e3779b1)) >>> 0,
    }
    if (lootVersion === 1) this.state.pickups = {version:1,forgePity:copy(forgePity),collected:[]}
    if (chosen.growthVersion === 1) this.state.base.tutorialWaves = chosen.tutorialWaves
    if (chosen.growthVersion === 1) {
      this.state.yujian = newYujianState(this.state.player,0,chosen)
    }
    // The legacy field name weaponFocusCount now carries the equipped RING's
    // immutable initial count. Campaign persists focusCount by ringId on finish.
    // Receipt ordinals keep every target/projectile of the fifth cast empowered,
    // even when a later cast hits first or the game is restored between hits.
    if (chosen.weapon) this.state.weaponState = {
      ringId: chosen.ring?.id ?? null,
      focusCount: training ? 0 : chosen.weaponFocusCount,
      effectiveCasts: 0, nextCastId: 1, casts: [],
      entryMaxHp: this.state.player.maxHp,
    }
    if (chosen.weapon || chosen.growthVersion === 1) this.state.actions = newAttackActions()
    if (chosen.armor) this.state.armorState = newArmorState(chosen)
    if (chosen.evolutions.includes('evo_wanjian')) this.state.cooldowns.evo_wanjian = 0
    this._registerWave()
    this._breakthroughNode()
  }

  static restore(snapshot) {
    if (!validateTowerSnapshot(snapshot)) throw new TypeError('Invalid tower snapshot')
    const run = Object.create(TowerRun.prototype)
    run._playtestAssist = false
    run.state = copy(snapshot)
    return run
  }

  snapshot() { return copy(this.state) }
  // Only the isolated playtest host opts in. Never persisted or inherited by
  // restore; ordinary runs and balance simulations keep the normal combat path.
  // Rebase permanent development XP without changing earned combat rewards.
  setDeveloperCultivation(xp) {
    const s = this.state
    if (s.phase !== 'paused' || !uint(xp, TOWER_XP_CAP) || xp < s.player.xp) {
      throw new RangeError('Invalid developer cultivation')
    }
    const next = copy(s)
    next.base.xp += xp - next.player.xp
    next.player.xp = xp
    Object.assign(next.player, stats(xp, next.loadout))
    const entryMaxHp = stats(next.base.xp, next.loadout).maxHp
    if (next.weaponState) next.weaponState.entryMaxHp = entryMaxHp
    if (!validateTowerSnapshot(next)) throw new TypeError('Invalid developer snapshot')
    this.state = next
  }
  setPlaytestAssist(enabled) {
    if (typeof enabled !== 'boolean') throw new TypeError('Invalid playtest assist flag')
    this._playtestAssist = enabled
  }
  // Campaign has already authorized learning and paid its point/book costs.
  // Updating a detached candidate makes a rejected change atomic; callers get
  // a detached snapshot suitable for the same persistence transaction.
  setGrowthLoadout(loadout) {
    loadout = {...loadout, classId: loadout?.classId === undefined ? this.state.loadout.classId : loadout.classId}
    loadout=applyEquipmentSkillLevels(loadout)
    const s = this.state
    if (s.phase !== 'paused' || s.loadout.growthVersion !== 1 || loadout?.growthVersion !== 1
      || loadout.classId !== s.loadout.classId || !validLoadout(loadout, s.player.xp) || !sameWeapon(s.loadout, loadout)
      || loadout.tutorialWaves !== s.loadout.tutorialWaves || loadout.skillsInitialized !== s.loadout.skillsInitialized || !validateTowerSnapshot(s)) {
      throw new TypeError('Invalid paused growth update')
    }
    const next = this.snapshot()
    next.loadout = copy(loadout)
    retimeYujian(next.yujian, next.time, s.loadout, next.loadout)
    if ((loadout.active.sj_yujian||0)<(s.loadout.active.sj_yujian||0)) {
      next.projectiles=next.projectiles.filter(p=>p.source!=='sj_yujian')
      next.casts=next.casts.filter(c=>c.skill!=='sj_yujian')
      next.yujian.ready=Math.min(10,next.yujian.ready,loadout.active.sj_yujian||0)
      next.yujian.head%=10
      if(next.weaponState) {
        const live=new Set([...next.casts,...next.projectiles,...next.zones,
          ...(next.actions?.basic ? [next.actions.basic] : [])].map(c=>c.weaponCastId))
        next.weaponState.casts=next.weaponState.casts.filter(c=>live.has(c.id))
      }
    }
    readyNewSkills(next)
    Object.assign(next.player, stats(next.player.xp, next.loadout))
    if (!validateTowerSnapshot(next)) throw new TypeError('Invalid updated growth snapshot')
    this.state = next
    return this.snapshot()
  }
  // Equipment changes are committed by Campaign while the backpack pauses time.
  // End outgoing attacks so their snapshotted affixes cannot mix with new gear.
  setEquipmentLoadout(loadout) {
    loadout = {...loadout, classId: loadout?.classId === undefined ? this.state.loadout.classId : loadout.classId}
    loadout = applyEquipmentSkillLevels(loadout)
    const s = this.state
    if (s.phase !== 'paused' || !validateTowerSnapshot(s)
      || loadout?.growthVersion !== 1 || loadout.classId !== s.loadout.classId
      || !validLoadout(loadout, s.player.xp)) throw new TypeError('Invalid paused equipment update')
    const next = this.snapshot()
    next.loadout = copy(loadout)
    retimeYujian(next.yujian, next.time, s.loadout, next.loadout)
    next.casts = []
    next.projectiles = next.projectiles.filter(p => p.hostile)
    next.swordBursts = []; next.swordBurstShots = []
    next.effects = next.effects.filter(e => !['sword_burst','sword_burst_charge','sword_burst_hit'].includes(e.kind))
    next.zones = next.zones.filter(z => z.hostile)
    next.actions.basic = null; next.actions.current = null; next.actions.orbit = null
    next.actions.waiting = {}
    next.weaponState = {ringId:loadout.ring?.id ?? null,focusCount:loadout.weaponFocusCount,
      effectiveCasts:0,nextCastId:1,casts:[],entryMaxHp:stats(next.base.xp,loadout).maxHp}
    if (next.yujian) next.yujian.ready = Math.min(next.yujian.ready,loadout.active.sj_yujian||0)
    readyNewSkills(next)
    Object.assign(next.player,stats(next.player.xp,loadout))
    next.player.hp = Math.min(next.player.hp,next.player.maxHp)
    next.player.mana = Math.min(next.player.mana,next.player.maxMana)
    next.base.hp = Math.min(next.base.hp,stats(next.base.xp,loadout).maxHp)
    // A new equipment segment has a different mana capacity/regeneration rate.
    // Rebase accounting without granting mana or advancing simulation time.
    next.base.mana = Math.min(next.player.mana,stats(next.base.xp,loadout).maxMana)
    next.manaState = {spent:0,recovered:next.player.mana-next.base.mana}
    if (s.loadout.armorId !== loadout.armorId) {
      delete next.armorState
      if (loadout.armor) {
        next.armorState = newArmorState(loadout)
        if ('lastHitAt' in next.armorState) next.armorState.lastHitAt = next.time
        if (armorEffectValue(loadout,'lowHealthShield')) {
          next.armorState.shieldUntil = next.time + 6
          next.armorState.shieldReadyAt = next.time + 20
        }
      }
    }
    if (next.armorState) {
      next.armorState.healedTotal = Math.min(next.armorState.healedTotal,maximumRegenerationAmount(next.player.maxHp,loadout)*Math.floor(next.ticks/180))
      if ('shield' in next.armorState) next.armorState.shield = Math.min(next.armorState.shield,next.player.maxHp*armorEffectValue(loadout,'lowHealthShield')/100)
    }
    if (!validateTowerSnapshot(next)) throw new TypeError('Invalid updated equipment snapshot')
    this.state = next
    return this.snapshot()
  }
  setInput(x, y) {
    if (this.state.phase !== 'playing') return
    if (!finite(x) || !finite(y)) throw new RangeError('Invalid movement')
    const length = Math.max(1, Math.hypot(x, y))
    this.state.input = { x: x / length, y: y / length }
  }
  // Optional host bridge. Null means geometry-only visibility, never a claim of
  // device-camera validation. followPlayer opts into per-tick camera movement;
  // absent/false retains a fixed rectangle. Setting it does not advance time.
  setViewport(view) {
    if (!validView(view)) throw new RangeError('Invalid viewport')
    this.state.view = copy(view)
  }
  pause() { if (this.state.phase === 'playing') this.state.phase = 'paused' }
  resume() {
    const s=this.state
    if(s.phase==='paused'){
      if(s.breakthrough?.safe && breakthroughReady(s.player.xp))s.breakthrough.ignoredGate=s.player.xp
      s.phase='playing'
    }
  }
  requestBreakthrough() {
    if(!this.state.training && this.state.breakthrough)this.state.breakthrough.requested=true
  }
  _breakthroughNode() {
    const s=this.state,b=s.breakthrough
    if(!b || s.training)return
    b.safe=true
    if(b.requested || breakthroughReady(s.player.xp)&&b.ignoredGate!==s.player.xp){s.phase='paused';b.requested=false}
  }
  commitBreakthrough(event) {
    const s=this.state,b=s.breakthrough
    if(!b?.safe || s.phase!=='paused' || !breakthroughReady(s.player.xp))throw new Error('safe-node-required')
    b.events.push(event)
    s.player.xp++
    Object.assign(s.player,stats(s.player.xp,s.loadout))
    s.player.hp=s.player.maxHp
  }
  abandon() {
    if (['playing', 'paused'].includes(this.state.phase)) {
      this.state.phase = 'abandoned'; collectAllPickups(this)
    }
  }

  advance(dt, onCast) {
    if (!finite(dt) || dt < 0 || dt > 60) throw new RangeError('Invalid simulation interval')
    const s = this.state
    if (s.phase !== 'playing') return s
    s.remainder += dt
    while (s.remainder + EPS >= STEP && s.phase === 'playing') {
      s.remainder = Math.max(0, s.remainder - STEP)
      this._tick(onCast)
    }
    // A terminal result cannot bank unplayed wall time into a later simulation.
    if (s.phase !== 'playing') s.remainder = 0
    s.remainder = Math.round(s.remainder * 1e12) / 1e12
    return s
  }

  _random() {
    let x = this.state.rng
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5
    this.state.rng = x >>> 0
    return this.state.rng / 4294967296
  }
  _id(prefix) { return `${prefix}${this.state.nextId++}` }
  _passive(id, key, loadout = this.state.loadout) {
    const lv = loadout.passive[id]
    return lv ? levelValue(id, key, lv, loadout) : 0
  }
  _evolved(id, loadout = this.state.loadout) { return loadout.evolutions.includes(id) }
  _evolutionBudget(id, loadout = this.state.loadout) {
    return loadout.growthVersion === 1 ? GEVO[id].budgetMultipliers[loadout.evolutionLevels[id] - 1] : 1.1
  }
  _effect(kind, x, y, radius, extra = {}) {
    const effect = { id: this._id('fx'), kind, x, y, radius,
      hostile: false, startedAt: this.state.time, expiresAt: this.state.time + .25, ...extra }
    this.state.effects.push(effect)
    return effect
  }
  _registerWave() {
    const s = this.state
    s.waveStartedAt = s.time
    s.waveKilled = 0
    s.supportReleased = false
    s.supportAt = -1
    s.pending = plan(s).map(p => ({ ...p, retryAt: s.time, waitingSince: s.time }))
    s.wavePlanned = s.pending.length
    s.reserved = []
  }
  _spawnSafe(point, radius, ignore = '') {
    const s = this.state
    return (s.arenaVersion !== 1 || clearPillars(point, radius))
      && distance(point, s.player) >= 280
      && (s.arenaVersion === 1 ? insideHex(point, radius)
        : point.x >= BOUNDS.xmin + radius && point.x <= BOUNDS.xmax - radius
          && point.y >= BOUNDS.ymin + radius && point.y <= BOUNDS.ymax - radius)
      && [...s.enemies, ...s.reserved].every(e => e.id === ignore
        || distance(point, e) >= Math.max(92, radius + e.radius + 16))
  }
  _spawn() {
    const s = this.state, cap = FLOORS[s.floor - 1].concurrent_cap
    for (const r of [...s.reserved]) {
      if (r.readyAt > s.time + EPS) continue
      s.reserved = s.reserved.filter(x => x.id !== r.id)
      if (!this._spawnSafe(r, r.radius, r.id)) {
        const { x, y, radius, readyAt, ...pending } = r
        s.pending.push({ ...pending, retryAt: s.time + .25 })
      } else s.enemies.push(this._enemy(r))
    }
    for (const p of [...s.pending]) {
      if (s.enemies.length + s.reserved.length >= cap) break
      if (p.retryAt > s.time || (p.trigger === 'half' && !s.supportReleased)) continue
      if (A[p.archetype].role === 'elite'
        && (s.enemies.some(e => !e.temporary && e.role === 'elite')
          || s.reserved.some(e => A[e.archetype].role === 'elite'))) continue
      const due = (p.trigger === 'half' ? s.supportAt : s.waveStartedAt) + p.at
      if (s.time + EPS < due) continue
      const preferred = PORTALS.find(portal => portal.id === p.portal)
      const reservedPortals = s.floor === 1 ? FLOOR01.waves[s.wave - 1].reserved_portals : []
      const portals = (s.time - p.waitingSince >= 15 ? [preferred, ...PORTALS.filter(x => x !== preferred)] : [preferred])
        .filter(portal => !reservedPortals.includes(portal.id))
      const radius = radiusOf(p.archetype)
      const point = portals.flatMap(x => x.candidates).find(candidate => this._spawnSafe(candidate, radius))
      if (!point) { p.retryAt = s.time + .25; continue }
      s.pending = s.pending.filter(x => x.id !== p.id)
      s.reserved.push({ ...p, x: point.x, y: point.y, radius, readyAt: s.time + p.warning })
    }
  }
  _enemy(unit) {
    const s = this.state, a = A[unit.archetype]
    const authored = towerEnemyStats(a, s.floor, s.wave)
    const enemy = { id: unit.id, archetype: unit.archetype, name: a.name,
      family: familyOf(a.id), role: a.role, rank: a.rank, x: unit.x, y: unit.y,
      ...authored, maxHp: authored.hp, radius: radiusOf(a.id),
      woundBudget: 0, woundPhysicalBudget: 0, woundUntil: 0, orbitNextAt: 0,
      ai: { mode: 'approach', attack: null, readyAt: s.time + .8, graceUntil: s.time + .8,
        until: 0, eligibleSince: -1, sequence: 0,
        cooldowns: a.role === 'normal' && normalSkillKind(familyOf(a.id))
          ? { [normalSkillKind(familyOf(a.id))]: s.time + NORMAL_SKILL_FIRST_DELAY } : {},
        faceX: 0, faceY: -1,
        orbitSign: this._random() < .5 ? -1 : 1, offset: this._random() * Math.PI * 2,
        phase: 1, transitionUntil: 0, transitionPending: false,
        entryUntil: s.time + (s.floor === 1 && a.role === 'boss' ? 1.2 : .8) } }
    initializeMonsterMechanics(this, enemy)
    return enemy
  }

  _targets(origin, reach, cap = Infinity) {
    return this.state.enemies.filter(e => e.hp > 0 && distance(e, origin) <= reach + e.radius
      && (this.state.arenaVersion !== 1 || pillarSight(origin,e)))
      .sort((a, b) => targetPriority(this, a) - targetPriority(this, b)
        || distance(a, origin) - distance(b, origin) || a.id.localeCompare(b.id)).slice(0, cap)
  }

  _separateBody(actor, other) {
    const radius = standingDistance(actor, other)
    if (distance(actor, other) >= radius - EPS) return
    const dir = facing(actor.x - other.x, actor.y - other.y)
    // Try the closest direction first. A wall or pillar can block it; rotating
    // the contact point keeps both bodies on legal ground without moving the
    // stationary actor or changing combat hitbox sizes.
    for (const angle of [0, .25, -.25, .5, -.5, 1, -1, Math.PI / 2, -Math.PI / 2, Math.PI]) {
      const x = dir.x * Math.cos(angle) - dir.y * Math.sin(angle)
      const y = dir.x * Math.sin(angle) + dir.y * Math.cos(angle)
      const candidate = { x: other.x + x * (radius + 1e-7),
        y: other.y + y * (radius + 1e-7), radius: actor.radius }
      boundActor(candidate, this.state.arenaVersion)
      if (distance(candidate, other) >= radius - EPS) {
        actor.x = candidate.x; actor.y = candidate.y
        return
      }
    }
  }

  _tick(onCast) {
    const s = this.state
    if(s.breakthrough)s.breakthrough.safe=false
    s.ticks++
    s.time = s.ticks / 60
    tickSpirit(s)
    this._pruneWeaponState()
    const p = s.player, oldPlayer = { x: p.x, y: p.y }
    const slow = s.zones.some(z => z.kind === 'web' && z.phase === 'active'
      && distance(z, p) <= z.radius + 18
      && (s.arenaVersion !== 1 || pillarSight(z,p))) ? .75 : 1
    const control = s.monsterControl
    const mechanicSlow = control && s.time < control.slowUntil ? 1 - control.slowFraction : 1
    const slowResistance = this._passive('sj_flight', 'slow_resistance')
    // Resist only the strongest slow's magnitude; roots still stop all movement.
    const movementMultiplier = control && s.time < control.rootUntil ? 0
      : 1 - (1 - Math.min(slow, mechanicSlow)) * (1 - slowResistance)
    p.x += s.input.x * p.moveSpeed * STEP * movementMultiplier
    p.y += s.input.y * p.moveSpeed * STEP * movementMultiplier
    boundActor(p, s.arenaVersion)
    // Input stops at living bodies; an already overlapping restored/spawned
    // enemy is moved away below instead of displacing the player.
    for (let pass = 0; pass < 4; pass++) {
      for (const e of s.enemies) {
        if (e.hp > 0 && distance(oldPlayer, e) >= standingDistance(p, e) - EPS)
          this._separateBody(p, e)
      }
    }
    if (s.enemies.some(e => e.hp > 0 && distance(oldPlayer, e) >= standingDistance(p, e) - EPS
      && distance(p, e) < standingDistance(p, e) - EPS)) Object.assign(p, oldPlayer)
    const inputPosition = { x: p.x, y: p.y }
    if (s.view?.followPlayer === true) {
      const dx = p.x - oldPlayer.x, dy = p.y - oldPlayer.y
      s.view.xmin += dx; s.view.xmax += dx
      s.view.ymin += dy; s.view.ymax += dy
    }
    if (Math.hypot(s.input.x, s.input.y) > EPS) {
      const dir = facing(s.input.x, s.input.y)
      p.faceX = dir.x; p.faceY = dir.y
    }
    s.effects = s.effects.filter(e => e.expiresAt > s.time)
    s.gateEntries = s.gateEntries.filter(e => e.expiresAt > s.time)
    const incoming = [], outgoing = []
    this._enemyActions(incoming, oldPlayer)
    const drainMonsterProjectiles = tickMonsterMechanics(this, incoming)
    // Preserve swept charge contacts, then keep the final bodies apart.
    for (const e of s.enemies) if (e.hp > 0) {
      // A live charge traverses its warned corridor until contact; separating
      // its enlarged art before the swept hurtbox hits would cancel the hit.
      if (e.ai.mode === 'active' && e.ai.attack?.kind === 'charge' && !e.ai.attack.hit) continue
      if (e.ai.attack?.kind === 'charge') this._separateBody(p, e)
      this._separateBody(e, p)
    }
    if (s.view?.followPlayer === true) {
      const dx = p.x - inputPosition.x, dy = p.y - inputPosition.y
      s.view.xmin += dx; s.view.xmax += dx
      s.view.ymin += dy; s.view.ymax += dy
    }
    this._skills(outgoing, onCast, oldPlayer)
    if(s.loadout.growthVersion===1) {
      s.yujian ||= newYujianState(p,s.time,s.loadout)
      turnYujian(s.yujian,p.faceX,s.time)
      s.yujian.x += (p.x-s.yujian.x)*.3
      s.yujian.y += (p.y-s.yujian.y)*.3
    }
    this._projectiles(incoming, outgoing, oldPlayer)
    this._zones(incoming, outgoing, onCast)
    tickWeaponBleeds(s,outgoing)
    outgoing.push(...tickQingping(this))
    tickMonsterAttributes(s.enemies,s.time)
    for (const e of s.enemies) {
      if(s.loadout.growthVersion===1)continue
      if (e.woundBudget > 0) {
        const amount = Math.min(e.woundBudget, e.woundBudget * STEP / Math.max(STEP, e.woundUntil - s.time + STEP))
        const physical=clamp(amount*((e.woundPhysicalBudget??e.woundBudget)/e.woundBudget),0,amount)
        e.woundPhysicalBudget=clamp((e.woundPhysicalBudget??e.woundBudget)-physical,0,e.woundBudget-amount)
        e.woundBudget -= amount
        outgoing.push({ target: e.id, damage: amount, damageParts:{physical,magic:amount-physical}, direct: false, scaled: true, source: 'wound' })
      }
    }
    // Collect both sides before resolving deaths. A projectile already in flight
    // from an actor alive at tick start is not erased by its same-tick death.
    for (const hit of outgoing) this._damageEnemy(hit)
    tickSwordBursts(this)
    tickArmorEffects(s)
    if (!this._playtestAssist && p.hp > 0 && s.time + EPS >= s.hurtUntil && incoming.length) {
      incoming.sort((a, b) => b.damage - a.damage || a.id.localeCompare(b.id))
      const damage = incoming[0].damage * ENEMY_INCOMING_DAMAGE_MULTIPLIER
        * (1 - Math.min(.18, this._passive('vajra', 'reduction')))
        * equipmentDamageMultiplier(s.loadout, incoming[0].damageType ?? 'physical')
      const hpBefore=p.hp
      const armorHit=resolveArmorHit(s,damage)

      if (p.hp > 0) this._applyMonsterControl(incoming[0].control)
      s.hurtUntil = s.time + .6
      s.nextWindupAt = Math.max(s.nextWindupAt, s.hurtUntil)
      this._effect('player_hit', p.x, p.y, 24, { damage:armorHit.damage,absorbed:armorHit.absorbed,
        hpLoss:hpBefore-p.hp,maxHp:p.maxHp })
    }
    // Incoming lethal damage wins; regeneration never revives the player.
    this._regenerateHp()
    this._deaths()
    const boss = s.enemies.find(e => e.role === 'boss')
    if (s.wave === 20 && !s.supportReleased
      && (boss && boss.hp <= boss.maxHp / 2 || s.killLedger.some(k => k.wave === 20 && A[k.archetype].role === 'boss'))) {
      s.supportReleased = true
      s.supportAt = s.time
    }
    if (p.hp <= 0) {
      s.phase = 'lost'; collectAllPickups(this); this._cancelBodyAction()
      this._pruneWeaponState(); return
    }
    this._drops()
    this._spawn()
    this._requestAttacks(drainMonsterProjectiles)
    if (!s.pending.length && !s.reserved.length && !s.enemies.length && s.waveKilled === s.wavePlanned) {
      if (s.training) {
        // Reset only the private training ledger; training cannot become "won".
        s.killLedger = []; s.rawKillXp = 0
        this._registerWave()
      } else {
        const kind = FLOORS[s.floor - 1].waves[s.wave - 1].kind
        s.clearedWaves.push(s.wave)
        // Replays and partial runs never award point vouchers.
        if (kind === 'boss') s.earned.cores += 5 * (s.floor - 1)
        if (s.wave === 20) { s.phase = 'won'; collectAllPickups(this); this._cancelBodyAction() }
        else {
          s.wave++
          s.projectiles = []; s.zones = []; this._cancelBodyAction()
          this._registerWave()
          this._breakthroughNode()
        }
      }
    }
    this._pruneWeaponState()
  }

  _applyMonsterControl(control) {
    const s = this.state, current = s.monsterControl
    if (!current || !control) return
    if (control.slowFraction > 0 && control.slowSeconds > 0) {
      current.slowFraction = Math.min(.3, Math.max(
        s.time < current.slowUntil ? current.slowFraction : 0, control.slowFraction))
      current.slowUntil = Math.max(current.slowUntil, s.time + Math.min(3, control.slowSeconds))
    }
    if (s.time < current.immuneUntil) return
    const duration = Math.min(.8, Math.max(0, control.rootSeconds || 0))
    if (duration > 0) {
      current.rootUntil = s.time + duration
      current.immuneUntil = current.rootUntil + 3
      // A control hit must not be followed by a new unavoidable attack.
      s.nextWindupAt = Math.max(s.nextWindupAt, current.rootUntil + 1.5)
    }
    const dx = control.knockbackX || 0, dy = control.knockbackY || 0
    const length = Math.hypot(dx, dy)
    // Ground mechanics have their own damage shapes; do not knock the player
    // into one. Walls/pillars use the same swept body clearance as movement.
    if (length > 0 && !s.monsterMechanics?.zones.some(z => z.phase === 'active')) {
      const travel = clippedRay(s.player, dx / length, dy / length, Math.min(64, length), 18, s.arenaVersion)
      s.player.x += dx / length * travel
      s.player.y += dy / length * travel
      boundActor(s.player, s.arenaVersion)
    }
  }

  _pruneWeaponState() {
    const s = this.state, w = s.weaponState
    if (!w) return
    const live = new Set([...s.casts, ...s.projectiles, ...s.zones,
      ...(s.actions?.basic ? [s.actions.basic] : [])].map(item => item.weaponCastId))
    w.casts = w.casts.filter(c => live.has(c.id))
  }

  _weaponCast(skillId) {
    const w = this.state.weaponState
    if (!w || !DIRECT_CAST_SKILLS.includes(skillId)) return {}
    const id = w.nextCastId++
    w.casts.push({ id, skillId, ordinal: null, procTargets: [] })
    return { weaponCastId: id }
  }

  _attackContext() {
    const context = castContext(this.state)
    if (context.loadout.weapon && context.loadout.weaponEquipped !== false) {
      const roll = this._random()
      context.weaponAttack = rollWeaponAttack(context.loadout.weapon, roll)
      context.weaponMagicAttack = rollWeaponAttack(context.loadout.weapon, roll, 'magic')
    }
    return context
  }

  _basicTarget() {
    const s = this.state
    if (!s.actions || !s.loadout.weapon || s.loadout.weaponEquipped === false || s.player.hp <= 0) return null
    return this._targets(s.player, weaponAttackProfile(s.loadout.weapon).reach)[0] ?? null
  }
  _basicReady() { return !!this._basicTarget() && this.state.actions.readyAt <= this.state.time + EPS }
  _cancelBodyAction() {
    const s = this.state
    const windups = new Set(s.casts.map(c => c.windupEffectId).filter(Boolean))
    s.effects = s.effects.filter(e => !windups.has(e.id))
    s.casts = []
    if (s.actions) {
      s.actions.basic = null; s.actions.current = null; s.actions.waiting = {}
      s.actions.busyUntil = s.time; s.actions.bypasses = 0
    }
    this._pruneWeaponState()
  }
  _canStartSkill() { return canStartSkill(this.state.actions, this.state.time, this._basicReady()) }
  _startSkillAction(skill, duration) {
    startSkillAction(this.state.actions, this.state.time, duration, skill, this._basicReady())
  }
  _advanceBasic(outgoing) {
    const s = this.state, a = s.actions, b = a?.basic
    if (!b) return
    if (b.pulseIndex === 0 && s.time + EPS >= b.releaseAt) {
      b.pulseIndex = 1
      const profile = equipmentAttackProfile(b.castContext.loadout), p = s.player
      const target = this._targets(p, profile.reach).find(e => e.id === b.targetId
        && inSector(e, p, { x: b.dirX, y: b.dirY }, profile.reach, 110, e.radius))
      this._effect('basic_swing', p.x, p.y, profile.reach,
        { dirX: b.dirX, dirY: b.dirY, angle: 110, source: 'basic_attack', expiresAt: b.endsAt })
      if (target) outgoing.push({ target: target.id, damage: castAttack(b.castContext) * profile.coefficient,
        direct: true, source: 'basic_attack', castContext: b.castContext, weaponCastId: b.weaponCastId,
        impact: { skill: 'basic_attack', dirX: b.dirX, dirY: b.dirY, pulseIndex: 1, pulseCount: 1 } })
    }
    if (s.time + EPS >= b.endsAt) a.basic = null
  }
  _startBasic(onCast) {
    const s = this.state, a = s.actions
    if (!a || a.basic || a.busyUntil > s.time + EPS || a.readyAt > s.time + EPS) return
    const target = this._basicTarget()
    if (!target) return
    const profile = equipmentAttackProfile(s.loadout)
    const dir = facing(target.x - s.player.x, target.y - s.player.y)
    s.player.faceX = dir.x; s.player.faceY = dir.y
    a.readyAt = s.time + profile.interval
    a.busyUntil = s.time + profile.duration
    a.bypasses = 0
    a.basic = { skill: 'basic_attack', targetId: target.id, dirX: dir.x, dirY: dir.y,
      startedAt: s.time, releaseAt: s.time + profile.duration / 2, endsAt: a.busyUntil,
      pulseIndex: 0, castContext: this._attackContext(), ...this._weaponCast('basic_attack') }
    this._notifySkill(onCast, 'basic_attack', a.basic.releaseAt, dir)
  }

  _notifySkill(onCast, skill, releaseAt, dir, pulseIndex = 1, pulseCount = 1, startedAt = this.state.time) {
    if (typeof onCast !== 'function') return
    try {
      const body = skill === 'basic_attack' ? this.state.actions?.basic : this.state.actions?.current
      onCast(Object.freeze({ skill, startedAt, releaseAt,
        dirX: dir.x, dirY: dir.y, pulseIndex, pulseCount,
        ...(body?.skill === skill ? { bodyReleaseAt: body.releaseAt, endsAt: body.endsAt } : {}) }))
    } catch { /* Observers cannot interrupt deterministic combat. */ }
  }

  _growthOrbit(level, outgoing, oldPlayer) {
    const s = this.state, p = s.player, loadout = s.loadout
    const form = formFor('sj_wanjian', level, loadout)
    const evolved = form.id === 'evo_wuwo', field = evolved || form.motion === 'wuwo'
    if (!s.actions?.orbit || (!evolved && !(s.orbitUntil > s.time + EPS))) return
    const previous = s.actions.orbit.castContext.loadout
    if (previous.active.sj_wanjian !== level
      || (previous.evolutionLevels.evo_wuwo ?? 0) !== (loadout.evolutionLevels.evo_wuwo ?? 0)) return
    const bladeRadius = form.bladeWidth / 2
    // 2026-11-13: the base orbit runs on its own motion clock. A living monster inside the outer reach
    // speeds the swords up, none slows them down; the pace blends over form.paceRamp seconds.
    let clockBefore = s.time, clockAfter = s.time
    if (!evolved && form.combatPace) {
      const goal = this._targets(p, orbitReach(form)).length ? form.combatPace : form.idlePace
      const pace = finite(s.orbitPace) ? s.orbitPace : goal, step = (form.combatPace - form.idlePace) * STEP / form.paceRamp
      s.orbitPace = pace + Math.max(-step, Math.min(step, goal - pace))
      clockBefore = finite(s.orbitClock) ? s.orbitClock : s.time
      clockAfter = s.orbitClock = clockBefore + s.orbitPace * STEP
    }
    const sweeps = []
    for (let i = 0; i < form.swords; i++) {
      const before = orbitSwordPose(form, evolved ? Math.max(0, s.time - STEP) : clockBefore, i)
      const after = orbitSwordPose(form, clockAfter, i)
      const a = before.collision ?? before, b = after.collision ?? after
      sweeps.push([
        { x: oldPlayer.x + a.baseX, y: oldPlayer.y + a.baseY },
        { x: oldPlayer.x + a.tipX, y: oldPlayer.y + a.tipY },
        { x: p.x + b.tipX, y: p.y + b.tipY },
        { x: p.x + b.baseX, y: p.y + b.baseY },
      ])
    }
    const radius = form.radius + form.bladeLength / 2 + bladeRadius + distance(p, oldPlayer)
    const hits = this._targets(p, radius).filter(e => e.orbitNextAt <= s.time + EPS
      && (field && distance(e, p) <= form.innerRadius + e.radius
        || sweeps.some(points => inPolygon(e, points, e.radius + bladeRadius))))
      .slice(0, form.targetCap)
    if (!hits.length) return
    const context = { castContext: s.actions?.orbit?.castContext ?? castContext(s) }
    for (const e of hits) {
      const outer = distance(e, p) + e.radius >= form.radius - form.bladeLength / 2 - bladeRadius
      // 2026-11-13: blade (non-field) hits of the base orbit carry the per-level 4-sword compensation.
      const fieldHit = field && distance(e, p) <= form.innerRadius + e.radius
      const factor = evolved ? (outer ? this._evolutionBudget('evo_wuwo') : GEVO.evo_wuwo.innerMultiplier[loadout.evolutionLevels.evo_wuwo - 1])
        : GS.sj_wanjian.cycle_damage_multiplier * (fieldHit ? 1 : GS.sj_wanjian.blade_compensation?.[level - 1] ?? 1)
      outgoing.push({ target: e.id, damage: castAttack(context.castContext) * levelValue('sj_wanjian', 'damage', level, loadout) * factor,
        direct: true, source: form.id, ...context,
        impact: { skill: form.id, dirX: -(e.y-p.y) || 0, dirY: (e.x-p.x) || 1,
          pulseIndex: 1, pulseCount: 1, castId: `${form.id}:${s.time}` } })
      e.orbitNextAt = s.time + form.interval
    }
    this._effect(field ? 'wuwo' : 'orbit', p.x, p.y, form.radius,
      { ...formGeometry(form, 1, s.time), innerRadius: form.innerRadius,
        swords: form.swords, targetIds: hits.map(e => e.id) })
  }

  // Reserve only deterministic direct damage. Critical hits, fifth-cast procs
  // and future wounds are deliberately not promised before impact.
  _yujianDamage(target, damage, loadout) {
    const parts=mitigateMonsterDamage(target,this.state.time,splitDamage(damage,GS.sj_yujian.damageType))
    const profile=loadout.weapon?weaponAttackProfile(loadout.weapon):null
    return (parts.physical+parts.magic) * outgoingDamageFactor(loadout, 'sj_yujian', GS.sj_yujian.damageType, true)
      * (1-(profile?.bleedConversion??0)) * (1+(profile?.onHit??0)) * monsterDamageMultiplier(this,target)
  }

  _yujianUnreservedHp(target, outgoing=[]) {
    let remaining=target.hp
    for(const shot of this.state.projectiles) {
      if(shot.yujianSlot===undefined || shot.targetId!==target.id || shot.dissolveAt!==null
        || shot.expiresAt<=this.state.time || shot.hitIds.includes(target.id))continue
      remaining-=this._yujianDamage(target,shot.damage,shot.castContext.loadout)
    }
    for(const hit of outgoing)if(hit.source==='sj_yujian' && hit.target===target.id)
      remaining-=this._yujianDamage(target,hit.damage,hit.castContext?.loadout||this.state.loadout)
    return remaining
  }

  _castForm(c) {
    const loadout = c.castContext.loadout
    return c.formId === 'evo_wanjian'
      ? skillForm(c.formId, loadout.evolutionLevels.evo_wanjian, c.level)
      : formFor(c.skill, c.level, loadout)
  }

  _skillTarget(id, form, outgoing = []) {
    const p = this.state.player
    if (id === 'sj_wanjian') return p
    const reach = form.shape === 'cross' ? Math.hypot(form.width, form.width / 2) + form.bladeWidth / 2
      : form.shape === 'sector' ? form.radius : form.reach
    const targets = this._targets(p, reach * (id === 'sj_yujian' ? 1 + this._passive('sj_spirit', 'reach_bonus') : 1))
    if (id === 'sj_sancai') return sancaiTarget(targets, p, form.radius,
      (a, b) => this.state.arenaVersion !== 1 || pillarSight(a, b))
    if (id === 'sj_jinghong') return jinghongTarget(targets)
    return id === 'sj_yujian' ? targets.find(e => this._yujianUnreservedHp(e, outgoing) > EPS
      && this._yujianDamage(e, 1, this.state.loadout) > EPS) : targets[0]
  }

  _advanceSkillCasts(outgoing, onCast) {
    const s = this.state, p = s.player
    for (const c of [...s.casts]) {
      if (!c.formId) {
        if (c.releaseAt <= s.time + EPS) {
          this._releaseSkill(c, outgoing)
          s.casts = s.casts.filter(item => item !== c)
        }
        continue
      }
      const form = this._castForm(c)
      const timing = castActionTiming(form.id, form.hits ?? 1, equipmentCastSpeed(c.castContext.loadout,c.castContext.xp))
      if (!c.locked) {
        const target = this._skillTarget(c.formId === 'evo_wanjian' ? 'evo_wanjian' : c.skill, form, outgoing)
        if (target) {
          const dir = facing(target.x - p.x, target.y - p.y, c.dirX, c.dirY)
          c.dirX = dir.x; c.dirY = dir.y; c.targetX = target.x; c.targetY = target.y
        }
        if (s.time + EPS >= c.lockAt) {
          c.locked = true
          if (form.id === 'evo_tiandi') this._notifySkill(onCast, form.id, c.releaseAt,
            { x: c.dirX, y: c.dirY }, 1, c.pulseCount, c.startedAt)
        }
      }
      p.faceX = c.dirX; p.faceY = c.dirY
      if (s.actions.current) { s.actions.current.dirX = c.dirX; s.actions.current.dirY = c.dirY }
      c.x = p.x; c.y = p.y
      const effect = s.effects.find(e => e.id === c.windupEffectId)
      if (effect) Object.assign(effect, { x: p.x, y: p.y, dirX: c.dirX, dirY: c.dirY,
        faceX: c.dirX, faceY: c.dirY, toX: p.x + c.dirX * form.reach,
        toY: p.y + c.dirY * form.reach, locked: c.locked })
      if (c.releaseAt > s.time + EPS) continue
      if (c.pulseIndex > 0) this._notifySkill(onCast, form.id, s.time,
        { x: c.dirX, y: c.dirY }, c.pulseIndex + 1, c.pulseCount, c.startedAt)
      if (c.formId === 'evo_wanjian') {
        const line = facing(c.targetX - p.x, c.targetY - p.y, c.dirX, c.dirY)
        const total = castAttack(c.castContext) * levelValue('sj_yujian', 'damage', c.level, c.castContext.loadout)
          * convergenceRainMultiplier(c.castContext.loadout.evolutionLevels.evo_wanjian)
        this._zone('sword_rain', c.targetX, c.targetY, form.radius, total / form.hits,
          form.initialDelay, form.hits, form.targetCap, form.interval, false, true,
          { ...formGeometry(form, 0, s.time), formId: form.id,
            formLevel: c.castContext.loadout.evolutionLevels.evo_wanjian, parentLevel: c.level,
            originX: p.x, originY: p.y, dirX: line.x, dirY: line.y,
            faceX: line.x, faceY: line.y, castContext: c.castContext })
        c.pulseIndex++
      } else if (c.skill === 'sj_wanjian') {
        s.actions.orbit = { startedAt: s.time, castContext: c.castContext }
        if (c.formId !== 'evo_wuwo') { s.orbitUntil = s.time + GS.sj_wanjian.duration; s.orbitPace = undefined; if (!finite(s.orbitClock)) s.orbitClock = s.time }
        c.pulseIndex++
      } else this._releaseSkill(c, outgoing)
      if (c.pulseIndex < timing.releases.length) c.releaseAt = c.startedAt + timing.releases[c.pulseIndex]
      else s.casts = s.casts.filter(item => item !== c)
    }
  }

  _growthSkills(outgoing, onCast, oldPlayer) {
    const s = this.state, p = s.player, loadout = s.loadout, actions = s.actions
    this._advanceBasic(outgoing)
    this._advanceSkillCasts(outgoing, onCast)
    if (actions.current && s.time + EPS >= actions.busyUntil) actions.current = null
    if (loadout.active.sj_wanjian) this._growthOrbit(loadout.active.sj_wanjian, outgoing, oldPlayer)
    const convergenceDue = this._evolved('evo_wanjian') && s.cooldowns.evo_wanjian <= s.time + EPS
    const convergenceTarget = convergenceDue ? this._targets(p, 440)[0] : null
    const rainActive = s.zones.some(z => z.kind === 'sword_rain' && z.ticks > 0)
    const candidates = new Map()
    if (convergenceTarget && !rainActive && !s.casts.some(c => c.skill === 'sj_yujian')
      && !s.projectiles.some(shot => !shot.hostile && shot.source === 'sj_yujian'
        && (shot.yujianSlot === undefined || shot.dissolveAt === null))) {
      candidates.set('evo_wanjian', { id: 'sj_yujian', level: loadout.active.sj_yujian,
        form: skillForm('evo_wanjian', loadout.evolutionLevels.evo_wanjian, loadout.active.sj_yujian), target: convergenceTarget })
    }
    for (const [id, level] of Object.entries(loadout.active)) {
      if (id === 'sj_yujian' && !convergenceTarget && !rainActive) {
        const reserve = s.yujian, interval = yujianGenerationInterval(loadout)
        if (reserve.nextAt <= s.time + EPS) {
          reserve.ready = Math.min(10, level, reserve.ready + 1); reserve.nextAt = s.time + interval
        }
      }
      if (s.cooldowns[id] > s.time + EPS || s.casts.some(c => c.skill === id)
        || actions.current?.parent === id) continue
      if (id === 'sj_yujian' && (convergenceTarget || rainActive || !s.yujian.ready)) continue
      const form = formFor(id, level, loadout)
      if (form.id === 'evo_wuwo' && actions.orbit
        && actions.orbit.castContext.loadout.active.sj_wanjian === level
        && actions.orbit.castContext.loadout.evolutionLevels.evo_wuwo === loadout.evolutionLevels.evo_wuwo) continue
      const target = this._skillTarget(id, form, outgoing)
      if (target) candidates.set(id, { id, level, form, target })
    }
    const basicReady = this._basicReady()
    if (!basicReady) actions.bypasses = 0
    // Creator's loose array-spread transform does not consume Map iterators.
    updateSkillCandidates(actions, Array.from(candidates.keys()), s.time)
    const chosen = nextSkillCandidate(actions, s.time, basicReady)
    if (chosen) {
      const { id, level, form, target } = candidates.get(chosen)
      const cost=skillManaCost(form.id)
      if(p.mana<cost)trySpiritPill(s,cost)
      if(p.mana<cost){this._startBasic(onCast);return}
      p.mana-=cost;s.manaState.spent+=cost
      const timing = castActionTiming(form.id, form.hits ?? 1, equipmentCastSpeed(loadout,p.xp))
      this._startSkillAction(chosen, timing.duration)
      const dir = facing(target.x - p.x, target.y - p.y, p.faceX, p.faceY)
      p.faceX = dir.x; p.faceY = dir.y
      const c = { skill: id, level, x: p.x, y: p.y, targetX: target.x, targetY: target.y,
        dirX: dir.x, dirY: dir.y, releaseAt: s.time + timing.releases[0], startedAt: s.time,
        formId: form.id, pulseIndex: 0, pulseCount: form.hits ?? 1,
        lockAt: s.time + timing.lock, locked: false,
        castContext: this._attackContext(),
        ...(chosen === 'evo_wanjian' ? {} : this._weaponCast(id)),
        ...(id === 'sj_yujian' && chosen !== 'evo_wanjian' ? { swordCount: s.yujian.ready } : {}) }
      actions.current = { skill: form.id, parent: id, hits: form.hits ?? 1,
        startedAt: s.time, releaseAt: c.releaseAt, endsAt: actions.busyUntil,
        dirX: dir.x, dirY: dir.y, speed: equipmentCastSpeed(loadout,p.xp), castContext: copy(c.castContext) }
      s.casts.push(c)
      if (chosen === 'evo_wanjian') {
        s.cooldowns.evo_wanjian = s.time + skillCooldown(GEVO.evo_wanjian.rainCooldown, loadout)
        s.cooldowns.sj_yujian = c.releaseAt + form.duration + skillCooldown(GS.sj_yujian.cooldown, loadout)
      } else if (id !== 'sj_yujian' && form.id !== 'evo_wuwo') {
        s.cooldowns[id] = s.time + skillCooldown(GEVO[form.id]?.cooldown ?? GS[id].cooldown, loadout)
      }
      this._notifySkill(onCast, form.id, c.releaseAt + form.initialDelay, dir, 1, c.pulseCount)
      // 起阵/成阵 is a windup-only effect; it is removed when the burst zone starts.
      if (form.id === 'sj_qinglian') c.windupEffectId = this._effect('qinglian', p.x, p.y, form.radius,
        { ...formGeometry(form, 0, s.time), dirX: dir.x, dirY: dir.y, faceX: dir.x, faceY: dir.y,
          phase: 'windup', expiresAt: c.releaseAt }).id
      if (form.id === 'evo_tiandi') c.windupEffectId = this._effect('tiandi_windup', p.x, p.y, form.width / 2,
        { ...formGeometry(form, 0, s.time), dirX: dir.x, dirY: dir.y, faceX: dir.x, faceY: dir.y,
          toX: p.x + dir.x * form.reach, toY: p.y + dir.y * form.reach,
          expiresAt: c.releaseAt, phase: 'windup' }).id
    }
    this._startBasic(onCast)
  }

  _releaseGrowthSkill(c, outgoing) {
    const s = this.state, p = s.player, loadout = c.castContext.loadout, id = c.skill
    const form = formFor(id, c.level, loadout)
    const attack = castAttack(c.castContext)
    const base = attack * levelValue(id, 'damage', c.level, loadout)
    const context = { castContext: c.castContext,
      ...(c.weaponCastId === undefined ? {} : { weaponCastId: c.weaponCastId }) }
    const dir = { x: c.dirX, y: c.dirY }
    c.pulseIndex++
    context.impact = { skill: form.id, dirX: dir.x, dirY: dir.y,
      pulseIndex: c.pulseIndex, pulseCount: form.hits,
      castId: `${form.id}:${c.startedAt ?? s.time}:${c.x ?? p.x}:${c.y ?? p.y}` }
    if (id === 'sj_yujian') {
      s.yujian ||= newYujianState(p,s.time,s.loadout)
      const count=Math.min(form.swords,s.yujian.ready,c.swordCount ?? form.swords)
      const reach=form.reach*(1+this._passive('sj_spirit','reach_bonus',loadout))
      const targets = this._targets(p, reach)
      if (!targets.length || !count) return
      const face=c.dirX<0?-1:1
      for (let i = 0; i < count; i++) {
        let target
        for(let j=0;j<targets.length;j++) {
          const candidate=targets[(i+j)%targets.length]
          if(this._yujianUnreservedHp(candidate,outgoing)>EPS && this._yujianDamage(candidate,1,loadout)>EPS) {
            target=candidate;break
          }
        }
        if(!target)break
        const slot=s.yujian.head, hover=yujianHoverPose(slot,s.time,s.yujian)
        // The visual height starts at 46px, so keep collision coordinates in
        // ground space. Reject obstructed origins rather than firing through walls.
        const origin={x:hover.x,y:hover.y-46}
        const length=distance(p,origin)
        if(length>EPS && clippedRay(p,(origin.x-p.x)/length,(origin.y-p.y)/length,length,7,s.arenaVersion)<length-EPS)break
        const flightAt=s.time
        this._projectile(origin.x, origin.y, face*680, 0, 7, base * levelValue('sj_yujian','sword_damage_share',c.level,loadout), false,
          { ...formGeometry(form, i + 1, s.time), radius: 7, targetId: target.id,
            expiresAt: flightAt+reach/680+1, ...context,
            yujianSlot:slot, launchFace:face, gatherAt:s.time, flightAt,
            hoverX:hover.x,hoverY:hover.y,hoverAngle:yujianHeading(s.yujian,s.time),
            dissolveAt:null,trail:[] })
        s.yujian.ready--
        s.yujian.head=(s.yujian.head+1)%10
      }
    } else if (SWORD_QI_SOURCES.includes(id) && form.shape.endsWith('-projectile')) {
      // The release is only a projectile. It does not also settle the retired
      // instantaneous sector, and later waves get the current caster position.
      const offset = swordQiReleaseOffset(form)
      const x=p.x+dir.x*offset, y=p.y+dir.y*offset
      const range=swordQiTravelLimit(form.bladeKind,form.width,form.bladeWidth,
        {x,y},dir.x,dir.y,form.reach,s.arenaVersion,swordQiPoseIndex({source:id,pulseIndex:c.pulseIndex}))
      // A blade with no room at its release position is blocked by terrain.
      // Do not render an already out-of-bounds body or settle an invisible hit.
      if (range <= EPS) return
      this._projectile(x,y,dir.x*form.speed,dir.y*form.speed,form.bladeWidth/2,
        base*skillHitShare(id,c.level,c.pulseIndex),false,{
          ...formGeometry(form,c.pulseIndex,s.time), radius:form.bladeWidth/2,
          bladeKind:form.bladeKind,bladeWidth:form.bladeWidth,speed:form.speed,
          dirX:dir.x,dirY:dir.y,originX:x,originY:y,range,travelled:0,
          dissolveAt:null,
          expiresAt:s.time+range/form.speed+SWORD_QI_TAIL,...context,
        })
    } else if (id === 'sj_moon') {
      // One stationary elliptical sweep; the fading blade never adds hits.
      const targets=this._targets(p,form.radius).filter(e=>{
        const x=(e.x-p.x)*dir.x+(e.y-p.y)*dir.y
        const y=-(e.x-p.x)*dir.y+(e.y-p.y)*dir.x
        return Math.hypot(x,y*2)<=form.radius+e.radius
          && Math.abs(Math.atan2(y*2,x))<=form.angle*Math.PI/360
      }).slice(0,form.targetCap)
      for(const e of targets)outgoing.push({target:e.id,damage:base,direct:true,source:id,...context})
      this._effect('cross',p.x,p.y,form.radius,{
        ...formGeometry(form,1,s.time),expiresAt:s.time+form.duration,
        dirX:dir.x,dirY:dir.y,faceX:dir.x,faceY:dir.y,targetIds:targets.map(e=>e.id),...context,
      })
    } else if (id === 'sj_cross') {
      const targets=this._targets(p,form.radius).filter(e=>
        (e.x-p.x)*dir.x+(e.y-p.y)*dir.y>=0
        && inSector(e,p,dir,form.radius,form.angle,e.radius)).slice(0,form.targetCap)
      for(const e of targets)outgoing.push({target:e.id,damage:base,direct:true,source:id,...context})
      this._effect('cross',p.x,p.y,form.radius,{
        ...formGeometry(form,1,s.time),expiresAt:s.time+.9,
        dirX:dir.x,dirY:dir.y,faceX:dir.x,faceY:dir.y,targetIds:targets.map(e=>e.id),...context,
      })
    } else if (id === 'sj_arc') {
      const targets = this._targets(p, form.radius).filter(e => inSector(e, p, dir, form.radius, form.angle, e.radius))
        .slice(0, form.targetCap)
      for (const e of targets) outgoing.push({ target: e.id, damage: base * skillHitShare(id, c.level, c.pulseIndex), direct: true, source: id, ...context })
      this._effect('arc', p.x, p.y, form.radius, { ...formGeometry(form, c.pulseIndex, s.time),
        faceX: dir.x, faceY: dir.y, dirX: dir.x, dirY: dir.y, targetIds: targets.map(e => e.id) })
    } else if (id === 'sj_line') {
      c.x = p.x; c.y = p.y
      const reach = clippedRay(c, dir.x, dir.y, form.reach, form.width / 2, s.arenaVersion)
      const end = { x: c.x + dir.x * reach, y: c.y + dir.y * reach }
      const targets = this._targets(c, reach + form.width / 2)
        .filter(e => segmentDistance(e, c, end) <= form.width / 2 + e.radius).slice(0, form.targetCap)
      const total = form.id === 'evo_tiandi' ? base * GEVO.evo_tiandi.cooldown / GS.sj_line.cooldown
        * this._evolutionBudget('evo_tiandi', loadout) : base
      for (const e of targets) outgoing.push({ target: e.id, damage: total / form.hits, direct: true, source: form.id, ...context })
      this._effect(form.id === 'evo_tiandi' ? 'tiandi' : 'line', c.x, c.y, form.width / 2,
        { ...formGeometry(form, c.pulseIndex, s.time), radius: form.width / 2, reach,
          dirX: dir.x, dirY: dir.y, faceX: dir.x, faceY: dir.y, toX: end.x, toY: end.y,
          targetIds: targets.map(e => e.id) })
    } else if (id === 'sj_jinghong') {
      // The locked sword follows its target; each thrust is resolved in _jinghongPulse.
      const target = this._skillTarget(id, form, outgoing)
      if (!target) return
      const lock = facing(target.x - p.x, target.y - p.y, dir.x, dir.y)
      this._zone('jinghong', target.x, target.y, form.radius, base / form.hits, form.initialDelay,
        form.hits, form.targetCap, form.interval, false, true, { ...formGeometry(form, 0, s.time),
          formId: form.id, formLevel: c.level, parentLevel: c.level, targetId: target.id,
          originX: p.x, originY: p.y, dirX: lock.x, dirY: lock.y, faceX: lock.x, faceY: lock.y, ...context })
    } else if (id === 'sj_qinglian') {
      // The formation stays where it was cast. Its three judgment rounds are resolved in _qinglianPulse.
      this._zone('qinglian', p.x, p.y, form.radius, base, 0, form.hits, form.targetCap,
        form.interval, false, true, { ...formGeometry(form, 0, s.time), formId: form.id,
          formLevel: c.level, parentLevel: c.level, dirX: dir.x, dirY: dir.y, faceX: dir.x, faceY: dir.y,
          expiresAt: s.time + form.duration, ...context })
    } else if (id === 'sj_shadow' || id === 'sj_formation' || id === 'sj_sancai') {
      const formation = id !== 'sj_shadow', sancai = id === 'sj_sancai'
      const total = id === 'sj_formation' ? base * GS.sj_formation.ticks
        * (form.id === 'evo_sixiang' ? this._evolutionBudget('evo_sixiang', loadout) * GEVO.evo_sixiang.cooldown / GS.sj_formation.cooldown : 1) : base
      this._zone(sancai ? 'sancai' : formation ? 'formation' : 'shadow', c.targetX, c.targetY, form.radius,
        total / form.hits, form.initialDelay, form.hits, form.targetCap, form.interval || 1,
        false, !formation, { ...formGeometry(form, 0, s.time), formId: form.id,
          formLevel: loadout.evolutionLevels[form.id] ?? c.level, parentLevel: c.level,
          dirX: dir.x, dirY: dir.y, faceX: dir.x, faceY: dir.y,
          ...(sancai ? { expiresAt: s.time + form.duration } : {}), ...context })
    }
  }

  _skills(outgoing, onCast, oldPlayer = this.state.player) {
    const s = this.state, p = s.player, loadout = s.loadout
    const growth = loadout.growthVersion === 1
    if (growth) return this._growthSkills(outgoing, onCast, oldPlayer)
    const table = growth ? GS : S
    const value = (id, key, lv) => levelValue(id, key, lv, loadout)
    const context = growth ? { castContext: castContext(s) } : {}
    for (const [id, lv] of Object.entries(s.loadout.active)) {
      if (id === 'sj_wanjian') {
        const outer = value(id, 'radius', lv)
        for (const e of this._targets(p, outer, table[id].target_cap ?? 6)) {
          if (e.orbitNextAt > s.time + EPS) continue
          let factor = value(id, 'damage', lv)
          if (this._evolved('evo_wuwo')) factor *= distance(e, p) + e.radius >= outer / 2
            ? this._evolutionBudget('evo_wuwo') : (growth ? GEVO.evo_wuwo.innerMultiplier[loadout.evolutionLevels.evo_wuwo - 1] : .5)
          outgoing.push({ target: e.id, damage: p.attack * factor, direct: true, source: id, ...context })
          e.orbitNextAt = s.time + (table[id].hit_interval ?? .6)
          this._effect(this._evolved('evo_wuwo') ? 'wuwo' : 'orbit', p.x, p.y, outer)
        }
        continue
      }
      if (s.cooldowns[id] > s.time + EPS || s.casts.some(c => c.skill === id)) continue
      const reach = id === 'sj_arc' ? value(id, 'radius', lv) : value(id, 'reach', lv) ?? 360
      const target = this._targets(p, reach)[0]
      if (!target) continue
      const dir = facing(target.x - p.x, target.y - p.y, p.faceX, p.faceY)
      p.faceX = dir.x; p.faceY = dir.y
      const evolvedLine = id === 'sj_line' && this._evolved('evo_tiandi')
      const windup = evolvedLine ? (growth ? GEVO.evo_tiandi.windup : .9)
        : (table[id].windup ?? (id === 'sj_arc' ? .18 : .12))
      s.casts.push({ skill: id, level: lv, x: p.x, y: p.y, targetX: target.x, targetY: target.y,
        dirX: dir.x, dirY: dir.y, releaseAt: s.time + windup, ...context, ...this._weaponCast(id) })
      s.cooldowns[id] = s.time + skillCooldown(evolvedLine ? (growth ? GEVO.evo_tiandi.cooldown : 6) : table[id].cooldown, loadout)
      // Optional presentation notification: primitives only, no saved event queue
      // and no dependency on cooldown formulas or surviving projectiles.
      if (typeof onCast === 'function') {
        try {
          onCast(Object.freeze({ skill: id, startedAt: s.time, releaseAt: s.time + windup,
            dirX: dir.x, dirY: dir.y }))
        } catch { /* Rendering observers must never interrupt combat settlement. */ }
      }
      if (evolvedLine) this._effect('tiandi_windup', p.x, p.y, 14,
        { toX: p.x + dir.x * reach, toY: p.y + dir.y * reach, expiresAt: s.time + windup, phase: 'windup' })
    }
    if (this._evolved('evo_wanjian') && s.cooldowns.evo_wanjian <= s.time + EPS) {
      const target = this._targets(p, 440)[0]
      if (target) {
        const evolution = GEVO.evo_wanjian
        const cooldown = evolution.rainCooldown
        const ticks = growth ? evolution.rainTicks : 6
        const interval = growth ? evolution.rainTickInterval : .2
        const damage = growth ? value('sj_yujian', 'damage', loadout.active.sj_yujian)
          / table.sj_yujian.cooldown * (this._evolutionBudget('evo_wanjian') - evolution.regularMultiplier)
          * evolution.rainDamageBudgetSeconds / ticks : .352
        s.cooldowns.evo_wanjian = s.time + skillCooldown(cooldown, loadout)
        this._zone('sword_rain', target.x, target.y, growth ? evolution.rainRadius : 160,
          damage * p.attack, interval, ticks, growth ? evolution.rainTargetCap : 6, interval, false, true, context)
      }
    }
    for (const cast of s.casts.filter(c => c.releaseAt <= s.time + EPS)) {
      this._releaseSkill(cast, outgoing)
      s.casts = s.casts.filter(c => c !== cast)
    }
  }
  _releaseSkill(c, outgoing) {
    const s = this.state, p = s.player, id = c.skill, lv = c.level
    const loadout = c.castContext?.loadout ?? s.loadout
    const growth = loadout.growthVersion === 1, table = growth ? GS : S
    if (growth && c.formId) return this._releaseGrowthSkill(c, outgoing)
    const value = key => levelValue(id, key, lv, loadout)
    const evolved = evo => this._evolved(evo, loadout)
    const attack = c.castContext ? stats(c.castContext.xp, loadout).attack : p.attack
    const context = c.castContext ? { castContext: c.castContext } : {}
    if (c.weaponCastId !== undefined) context.weaponCastId = c.weaponCastId
    const dir = { x: c.dirX, y: c.dirY }
    const base = attack * value('damage')
    if (id === 'sj_yujian') {
      const count = value('swords'), reach = value('reach')
      const targets = this._targets(p, reach, value('target_cap'))
      const damage = (evolved('evo_wanjian')
        ? (growth ? base * GEVO.evo_wanjian.regularMultiplier : attack * 1.188) : base) / count
      for (let i = 0; i < (growth ? Math.min(count, targets.length) : count) && targets.length; i++) {
        const target = targets[growth ? i : i % targets.length]
        const heading = facing(target.x - p.x, target.y - p.y)
        this._projectile(p.x, p.y, heading.x * 680, heading.y * 680, 7,
          growth ? damage * count * (i === 0 ? 1 : levelValue('sj_yujian','secondary_share',lv,loadout)) : damage, false,
          { targetId: target.id, source: id, expiresAt: s.time + reach / 680 + .2, ...context })
      }
    } else if (id === 'sj_arc') {
      const radius = value('radius'), angle = table[id].angle ?? 90
      const targets = this._targets(c, radius).filter(e => inSector(e, c, dir, radius, angle, e.radius))
        .slice(0, table[id].target_cap ?? 6)
      targets.forEach(e => outgoing.push({ target: e.id, damage: base, direct: true, source: id, ...context }))
      this._effect('arc', c.x, c.y, radius, { shape: 'sector', angle, faceX: dir.x, faceY: dir.y })
    } else if (id === 'sj_line') {
      const reach = value('reach'), width = table[id].width ?? 28
      const end = { x: c.x + dir.x * reach, y: c.y + dir.y * reach }
      const damage = evolved('evo_tiandi') ? (growth
        ? base * GEVO.evo_tiandi.cooldown / table[id].cooldown * this._evolutionBudget('evo_tiandi', loadout)
        : 2.7225 * attack) : base
      this._targets(c, reach).filter(e => segmentDistance(e, c, end) <= width / 2 + e.radius)
        .slice(0, value('target_cap'))
        .forEach(e => outgoing.push({ target: e.id, damage, direct: true, source: id, ...context }))
      this._effect(evolved('evo_tiandi') ? 'tiandi' : 'line', c.x, c.y, width / 2,
        { toX: end.x, toY: end.y, width })
    } else if (id === 'sj_shadow') {
      this._zone('shadow', c.targetX, c.targetY, value('radius'), base, table[id].delay ?? .65,
        1, table[id].target_cap ?? 6, 1, false, true, context)
    } else if (id === 'sj_formation') {
      const evolution = evolved('evo_sixiang')
      const damage = evolution ? (growth ? base * this._evolutionBudget('evo_sixiang', loadout) : .22 * attack) : base
      const interval = table[id].hit_interval ?? .5
      const z = this._zone('formation', c.targetX, c.targetY, value('radius'),
        damage, interval, table[id].ticks ?? 6, table[id].target_cap ?? 8, interval, false, false, context)
      z.eyes = evolution ? (growth ? GEVO.evo_sixiang.eyes : 4) : 2 // One shared six-tick ledger.
    }
  }

  _projectile(x, y, vx, vy, radius, damage, hostile, extra = {}) {
    this.state.projectiles.push({ id: this._id('p'), x, y, vx, vy, radius, damage,
      hostile, hitIds: [], expiresAt: this.state.time + 4, source: 'enemy',
      ...(hostile ? {damageType:'physical'} : {}), ...extra })
  }
  _zone(kind, x, y, radius, damage, delay, ticks, targetCap, interval, hostile, direct, extra = {}) {
    const z = { id: this._id('z'), kind, x, y, radius, damage, hostile, direct,
      phase: 'windup', nextAt: this.state.time + delay, ticks, interval, targetCap,
      ...(hostile ? {damageType:kind === 'web' ? 'magic' : 'physical'} : {}),
      expiresAt: this.state.time + delay + (ticks - 1) * interval + .2, renderOnly: false, ...extra }
    this.state.zones.push(z)
    return z
  }
  _projectiles(incoming, outgoing, oldPlayer) {
    const s = this.state
    for (const shot of s.projectiles) {
      if(shot.yujianSlot!==undefined && shot.dissolveAt===null && shot.expiresAt<=s.time) {
        shot.dissolveAt=s.time;shot.expiresAt=s.time+YUJIAN_TAIL
      }
      if (shot.expiresAt <= s.time) continue
      if(shot.yujianSlot!==undefined) {
        if(shot.dissolveAt!==null)continue
        const pose=yujianVisualPose(shot,s.time)
        shot.trail.push({...pose,at:s.time})
        shot.trail=shot.trail.filter(a=>s.time-a.at<=YUJIAN_TAIL).slice(-24)
        if(s.time<shot.flightAt)continue
        let target=s.enemies.find(e=>e.id===shot.targetId&&e.hp>0)
        if(!target) {
          const level=shot.castContext.loadout.active.sj_yujian
          const reach=skillForm('sj_yujian',level).reach*(1+this._passive('sj_spirit','reach_bonus',shot.castContext.loadout))
          target=this._targets(s.player,reach).find(e=>this._yujianUnreservedHp(e,outgoing)>EPS
            && this._yujianDamage(e,shot.damage,shot.castContext.loadout)>EPS)
          if(target)shot.targetId=target.id
        }
        if(!target) {
          shot.dissolveAt=s.time;shot.expiresAt=s.time+YUJIAN_TAIL;continue
        }
        stepYujianFlight(shot,target,s.time,STEP)
        avoidYujianBoundary(shot,target,STEP,(dx,dy,length)=>s.arenaVersion===1?clipHexRay(shot,dx,dy,length,shot.radius):clippedRay(shot,dx,dy,length,shot.radius,s.arenaVersion))
      }
      if (shot.bladeKind) {
        if (shot.dissolveAt !== null) continue
        const old={x:shot.x,y:shot.y}
        shot.travelled=Math.min(shot.range,shot.travelled+shot.speed*STEP)
        shot.x=shot.originX+shot.dirX*shot.travelled
        shot.y=shot.originY+shot.dirY*shot.travelled
        const hits=s.enemies.filter(e=>e.hp>0 && !shot.hitIds.includes(e.id)
          && swordQiHits(shot.bladeKind,shot.width,shot.bladeWidth,old,shot,shot.dirX,shot.dirY,e,swordQiPoseIndex(shot)))
          .sort((a,b)=>distance(a,old)-distance(b,old)||a.id.localeCompare(b.id))
          .slice(0,Math.max(0,shot.targetCap-shot.hitIds.length))
        for(const e of hits) {
          shot.hitIds.push(e.id)
          outgoing.push({target:e.id,damage:shot.damage,direct:true,source:shot.source,
            castContext:shot.castContext,weaponCastId:shot.weaponCastId,
            impact:{...shot.impact,skill:shot.source,dirX:shot.dirX,dirY:shot.dirY,
              pulseIndex:shot.pulseIndex||1,pulseCount:shot.pulseCount||1,castId:shot.id}})
        }
        if(shot.travelled>=shot.range-EPS) {
          shot.dissolveAt=s.time;shot.expiresAt=s.time+SWORD_QI_TAIL
        }
        continue
      }
      if (!shot.hostile && shot.targetId && shot.yujianSlot===undefined) {
        const target = s.enemies.find(e => e.id === shot.targetId && e.hp > 0)
        if (target) {
          const speed = Math.hypot(shot.vx, shot.vy), dir = facing(target.x - shot.x, target.y - shot.y)
          shot.vx = dir.x * speed; shot.vy = dir.y * speed
        }
      }
      const old = { x: shot.x, y: shot.y }
      const speed=Math.hypot(shot.vx,shot.vy)
      const wall = shot.yujianSlot!==undefined && speed>0
        ? Math.min(STEP,clippedRay(old,shot.vx/speed,shot.vy/speed,speed*STEP,shot.radius,s.arenaVersion)/speed)
        : s.arenaVersion === 1 ? clipPillars(old,shot.vx,shot.vy,STEP,shot.radius) : STEP
      shot.x += shot.vx * wall; shot.y += shot.vy * wall
      if(wall < STEP - EPS) {
        shot.expiresAt=0
        if(shot.yujianSlot!==undefined) {
          shot.dissolveAt=s.time;shot.expiresAt=s.time+YUJIAN_TAIL
        }
      }
      if (shot.hostile) {
        const relativeOld = { x: old.x - oldPlayer.x + s.player.x, y: old.y - oldPlayer.y + s.player.y }
        if (segmentDistance(s.player, relativeOld, shot) <= 18 + shot.radius) {
          incoming.push({ id: shot.id, damage: shot.damage, damageType: shot.damageType ?? 'physical' })
          shot.expiresAt = 0
        }
      } else {
        const hits = s.enemies.filter(e => e.hp > 0 && !shot.hitIds.includes(e.id)
          && !(shot.castContext?.loadout.growthVersion === 1 && shot.source === 'sj_yujian'
            && shot.targetId && shot.targetId !== e.id)
          && segmentDistance(e, old, shot) <= e.radius + shot.radius)
          .sort((a, b) => distance(a, old) - distance(b, old))
        if (hits.length) {
          outgoing.push({ target: hits[0].id, damage: shot.damage, direct: true, source: shot.source,
            castContext: shot.castContext, weaponCastId: shot.weaponCastId,
            ...(shot.source==='sj_yujian' ? {impact:{...shot.impact,skill:shot.source,
              dirX:shot.vx,dirY:shot.vy,pulseIndex:shot.pulseIndex||1,pulseCount:shot.pulseCount||1,castId:shot.id}} : {}) })
          shot.hitIds.push(hits[0].id)
          shot.expiresAt = 0
          if(shot.yujianSlot!==undefined) {
            shot.dissolveAt=s.time;shot.expiresAt=s.time+YUJIAN_TAIL
          }
        }
      }
    }
    s.projectiles = s.projectiles.filter(p => p.expiresAt > s.time)
  }
  _growthZonePulse(z, outgoing, onCast) {
    const s = this.state, form = skillForm(z.formId, z.formLevel, z.parentLevel,
      z.castContext?.loadout?.trainedSkills?.active?.[z.formId] ?? z.parentLevel)
    if (z.kind === 'qinglian') return this._qinglianPulse(z, form, outgoing)
    if (z.kind === 'jinghong') return this._jinghongPulse(z, form, outgoing)
    const pulse = ++z.pulseIndex
    let origin = z, end = null, width = form.width, kind = z.kind, shape = form.shape
    let targets, terminal = false
    if (z.kind === 'shadow') {
      const offsets = [0, Math.PI / 2, Math.PI / 4, -Math.PI / 4]
      const angle = Math.atan2(z.dirY, z.dirX) + offsets[pulse - 1]
      const dx = Math.cos(angle), dy = Math.sin(angle)
      origin = { x: z.x - dx * form.radius, y: z.y - dy * form.radius }
      end = { x: z.x + dx * form.radius, y: z.y + dy * form.radius }
      if (s.arenaVersion === 1) {
        // A slash is a finite segment around its mark, not a shot entering
        // from outside. Keep its in-arena portion before applying pillar stops.
        const segment = clipHexSegment(origin, end, width / 2)
        if (!segment) return
        origin = segment.start
        end = segment.end
      }
    } else if (z.kind === 'sword_rain') {
      kind = 'convergence'; shape = 'line'; terminal = pulse === form.hits
      if (terminal) {
        origin = { x: z.originX, y: z.originY }
        const length = distance(origin, z) + form.radius
        end = { x: origin.x + z.dirX * length, y: origin.y + z.dirY * length }
        width = form.width * 2
        // The already-released convergence keeps running without a new body action.
        s.cooldowns.sj_yujian = Math.max(s.cooldowns.sj_yujian,
          s.time + skillCooldown(GS.sj_yujian.cooldown, z.castContext.loadout))
      } else {
        const angle = Math.atan2(z.dirY, z.dirX) + (pulse - 1) * Math.PI * 2 / form.swords
        origin = { x: z.x + Math.cos(angle) * form.radius, y: z.y + Math.sin(angle) * form.radius }
        end = { x: z.x, y: z.y }
      }
    }
    let extra = {}
    if (end) {
      const dir = facing(end.x - origin.x, end.y - origin.y)
      const reach = clippedRay(origin, dir.x, dir.y, distance(origin, end), width / 2, s.arenaVersion)
      end = { x: origin.x + dir.x * reach, y: origin.y + dir.y * reach }
      targets = this._targets(origin, reach + width / 2)
        .filter(e => segmentDistance(e, origin, end) <= width / 2 + e.radius).slice(0, form.targetCap)
      extra = { width, reach, dirX: dir.x, dirY: dir.y, faceX: dir.x, faceY: dir.y,
        toX: end.x, toY: end.y, terminal }
    } else if (form.shape === 'triangle' || form.shape === 'diamond') {
      targets = this._targets(z, form.radius)
        .filter(e => formationContains(z, e)).slice(0, form.targetCap)
    } else targets = this._targets(z, form.radius, form.targetCap)
    // Stored zone damage remains the average per pulse for snapshot validation.
    // Weight only the released shadow hit; the full cast budget is unchanged.
    const pulseDamage = z.kind === 'shadow'
      ? z.damage * form.hits * skillHitShare('sj_shadow', z.formLevel, pulse) : z.damage
    for (const e of targets) outgoing.push({ target: e.id, damage: pulseDamage, direct: z.direct, source: z.kind,
      impact: {skill:form.id,dirX:extra.dirX??0,dirY:extra.dirY??-1,
        pulseIndex:pulse,pulseCount:form.hits,castId:z.id??`${form.id}:${z.startedAt??s.time}`},
      ...(z.kind === 'shadow' ? { shadowImpact: {
        dirX: extra.dirX, dirY: extra.dirY, pulseIndex: pulse, pulseCount: form.hits } } : {}),
      castContext: z.castContext, weaponCastId: z.weaponCastId })
    this._effect(kind, origin.x, origin.y, form.radius,
      { ...formGeometry(form, pulse, s.time), shape, ...extra, targetIds: targets.map(e => e.id) })
  }

  // Each round (one second) judges one ring: outer, then middle, then inner. Every petal
  // of that ring that sweeps a target deals its share of the cast budget, so a target in
  // reach takes 16 + 12 + 8 = 36 hits per cast. Targets are not capped.
  _qinglianPulse(z, form, outgoing) {
    const s = this.state, pulse = ++z.pulseIndex
    const ring = form.rings[qinglianRingForPulse(form, pulse)]
    const perHit = z.damage * ring.share / ring.visualPetals
    const rows = this._targets(z, form.radius)
      .map(e => ({ e, hits: qinglianRoundHits(form, z, e, pulse) }))
      .filter(row => row.hits > 0)
    for (const { e, hits } of rows) {
      for (let i = 0; i < hits; i++) {
        outgoing.push({ target: e.id, damage: perHit, direct: true, source: 'sj_qinglian',
          impact: { skill: form.id, dirX: z.dirX, dirY: z.dirY, pulseIndex: pulse,
            pulseCount: form.hits, castId: z.id },
          castContext: z.castContext, weaponCastId: z.weaponCastId })
      }
    }
    this._effect('qinglian', z.x, z.y, form.radius,
      { ...formGeometry(form, pulse, s.time), shape: 'lotus', rings: form.rings,
        targetIds: rows.map(row => row.e.id) })
  }

  // One thrust per pulse on the locked enemy only. A dead or missing target is
  // replaced by the Boss/highest-HP enemy near the sword; with none, the thrust misses.
  _jinghongPulse(z, form, outgoing) {
    const s = this.state, pulse = ++z.pulseIndex
    let e = s.enemies.find(item => item.id === z.targetId && item.hp > 0)
    if (!e) e = jinghongTarget(this._targets(z, form.retargetRadius))
    if (!e) return
    z.targetId = e.id; z.x = e.x; z.y = e.y
    // The sword appeared on a deterministic random side and travels through the target.
    const spawn = jinghongSpawnDir(z.id, pulse, z.dirX, z.dirY), dirX = -spawn.x, dirY = -spawn.y
    outgoing.push({ target: e.id, damage: z.damage, direct: true, source: 'sj_jinghong',
      impact: { skill: form.id, dirX, dirY, pulseIndex: pulse, pulseCount: form.hits, castId: z.id },
      castContext: z.castContext, weaponCastId: z.weaponCastId })
    // The scar outlives the sword; the presentation reads its full window from this effect.
    this._effect('jinghong', e.x, e.y, e.radius, { ...formGeometry(form, pulse, s.time), castId: z.id, lockX: z.dirX, lockY: z.dirY,
      dirX, dirY, faceX: dirX, faceY: dirY, expiresAt: s.time + JINGHONG_SCAR, targetIds: [e.id] })
  }

  _zones(incoming, outgoing, onCast) {
    const s = this.state
    for (const z of s.zones) {
      if (z.renderOnly || z.ticks <= 0 || z.nextAt > s.time + EPS) continue
      z.phase = 'active'
      if (z.hostile) {
        if (!this._playtestAssist && distance(z, s.player) <= z.radius + 18
          && (s.arenaVersion !== 1 || pillarSight(z,s.player))) {
          incoming.push({ id: `${z.id}:${z.ticks}`, damage: z.damage, damageType: z.damageType ?? 'physical' })
        }
      } else if (z.formId) {
        this._growthZonePulse(z, outgoing, onCast)
      } else {
        this._targets(z, z.radius, z.targetCap).forEach(e =>
          outgoing.push({ target: e.id, damage: z.damage, direct: z.direct, source: z.kind,
            castContext: z.castContext, weaponCastId: z.weaponCastId }))
      }
      z.ticks--
      z.nextAt += z.interval
    }
    s.zones = s.zones.filter(z => z.expiresAt > s.time)
  }
  _damageEnemy(hit) {
    const s = this.state, e = s.enemies.find(e => e.id === hit.target && e.hp > 0)
    if (!e) return
    const loadout = hit.castContext?.loadout ?? s.loadout
    const skillId = weaponSkill(hit.source)
    const damageType = GS[skillId]?.damageType ?? 'physical'
    let damage = hit.damage
    const context = hit.castContext ?? castContext(s)
    const baseParts = hit.damageParts ?? (hit.scaled ? splitDamage(damage, damageType)
      : attackDamageParts(damage, damageType, castAttack(context), castMagicAttack(context)))
    let parts = { ...baseParts }
    let focus = false, critical = false
    if (!hit.scaled) {
      const isSkill = !!(GS[skillId] || GEVO[skillId])
      parts = scaleDamageParts(parts,
        outgoingDamageFactor(loadout, skillId, 'physical', isSkill),
        outgoingDamageFactor(loadout, skillId, 'magic', isSkill))
      if (damageType !== 'none') {
        const modifiers = loadout.weapon ? weaponDamageModifiers(loadout.weapon, skillId, damageType) : {critChance:0,critBonus:0}
        const ring = loadout.ring ? ringDamageModifiers(loadout.ring) : {critChance:0,critBonus:0}
        if (this._random() < clamp(this._passive('sj_heart', 'crit_chance', loadout) + ring.critChance + modifiers.critChance, 0, 1)) {
          critical = true
          parts = scaleDamageParts(parts, criticalMultiplier([ring.critBonus, modifiers.critBonus]))
        }
      }
    }
    // Bleed and legacy wound budgets already inherited their source's defenses.
    const resolvedDot=hit.scaled&&!hit.direct&&['weapon_bleed','wound'].includes(hit.source)
    if(!resolvedDot)parts=mitigateMonsterDamage(e,s.time,parts)
    damage = parts.physical + parts.magic
    // Weapon bleed inherits resolved damage and does not apply mitigation twice.
    if (!resolvedDot)
      damage *= monsterDamageMultiplier(this, e)
    const totalParts=parts.physical+parts.magic
    const physicalRatio=totalParts>0?parts.physical/totalParts:0
    const profile=loadout.weapon?weaponAttackProfile(loadout.weapon):null
    const convertible=!hit.scaled&&damageType!=='none'
    const dotBonus=(loadout.ring?.affixes.find(a=>a.type==='dotDamage')?.value??0)/100
    const split=splitDotConversion(damage,damage*physicalRatio,
      convertible?(profile?.bleedConversion||0):0,(profile?.bleed||0)+dotBonus)
    const effective=Math.min(e.hp,split.direct*scarDamageMultiplier(e,s.time,hit))
    const physical=effective*physicalRatio,damageParts={physical,magic:effective-physical}
    e.hp=Math.max(0,e.hp-effective)
    if(e.hp>0){
      if(split.bleed>0)addWeaponBleed(e,s.time,split.bleed,split.bleedPhysical)
      if(loadout.growthVersion===1&&this._passive('sj_mark','vulnerability',loadout)>0
        &&isScarDirectHit(hit)&&effective>0
        &&(hit.source==='basic_attack'||GS[skillId]?.kind==='active'||GEVO[skillId]?.kind==='evolution'))
        addQingping(this,e)
    }else {delete e.scarDebuff;delete e.armorBreak}
    if(hit.direct&&!hit.scaled&&loadout.growthVersion!==1){
      const wound=effective*this._passive('sj_mark','wound_share',loadout)
      e.woundPhysicalBudget=(e.woundPhysicalBudget??e.woundBudget)+wound;e.woundBudget+=wound;e.woundUntil=s.time+2
      const gate=effective*this._passive('sj_gate','share',loadout)
      if(gate)s.gateEntries.push({amount:gate,expiresAt:s.time+10})
    }
    chargeSwordBurst(this,e,hit,effective,loadout)
    if (e.hp <= 0) e.killedBy = hit.source
    this._effect('hit', e.x, e.y, 12, { damage: effective, damageParts, source: hit.source,
      targetId: e.id, targetRadius: e.radius,
      ...(hit.impact ? {impact:{...hit.impact}} : {}),
      ...(hit.source === 'shadow' && hit.shadowImpact ? { shadowImpact: { ...hit.shadowImpact } } : {}),
      ...(critical ? { critical: true } : {}),
      ...(loadout.weapon && focus ? { weaponFocus: true } : {}) })
    // Attached damage is a fraction of this resolved hit, including its critical
    // multiplier and mitigation. It never rolls another crit or creates procs.
    if (loadout.weapon && !hit.scaled && damageType !== 'none' && damage > 0 && e.hp > 0) {
      const fraction=profile.onHit
      if (fraction > 0) {
        const bonus = Math.min(e.hp, split.direct * fraction)
        e.hp -= bonus
        if (e.hp <= 0) {e.killedBy = 'weapon_on_hit';delete e.scarDebuff;delete e.armorBreak}
        this._effect('hit', e.x, e.y, 8, { damage: bonus, source: 'weapon_on_hit',
          damageParts: { physical: totalParts ? bonus * parts.physical / totalParts : 0,
            magic: totalParts ? bonus * parts.magic / totalParts : bonus },
          targetId: e.id, targetRadius: e.radius, attached: true })
      }
    }
  }

  _regenerateHp() {
    const s = this.state, p = s.player, a = s.armorState
    if (s.ticks % 180 !== 0 || p.hp <= 0 || p.hp >= p.maxHp) return
    const amount = Math.min(p.maxHp - p.hp, regenerationAmount(p.maxHp, s.loadout,s))
    p.hp += amount
    if (a) a.healedTotal += amount
  }
  _gainXp(amount) {
    const s = this.state, p = s.player
    let previous = cultivationAt(p.xp)
    const gained = Math.min(cultivationXpCap(p.xp) - p.xp, amount)
    p.xp += gained
    s.earned.xp += gained
    Object.assign(p, stats(p.xp, s.loadout))
    // Incoming damage resolves before kill rewards. Leveling cannot revive a
    // player killed in this tick, and loading a snapshot never enters this path.
    if (p.hp <= 0) return
    const finalLevel = cultivationAt(p.xp).level
    for (let level = previous.level + 1; level <= finalLevel; level++) {
      const lowerLevel = level - 1
      const levelXp = cultivationLevelXp(level)
      const next = cultivationAt(levelXp)
      const maxHp = stats(levelXp, s.loadout).maxHp
      p.hp = next.realm !== previous.realm
        ? maxHp
        : Math.min(maxHp, p.hp + maxHp * .3)
      previous = next
    }
  }
  _deaths() {
    const s = this.state
    const coreDrops = s.loot ? buildCoreDropPlan(s.floor, s.loot.seed) : null
    // Gate-triggered deaths may award kills, but never trigger another gate.
    for (let pass = 0; pass < 2; pass++) {
      const dead = s.enemies.filter(e => e.hp <= 0)
      onMonsterDeaths(this, dead)
      s.enemies = s.enemies.filter(e => e.hp > 0)
      for (const e of dead) {
        if (!e.temporary) {
          s.waveKilled++
          const kill = { id: e.id, archetype: e.archetype, wave: s.wave }
          if (coreDrops) kill.coreRank = coreRankFor(s, kill, coreDrops)
          s.killLedger.push(kill)
          const xp = towerKillXp(s.floor, s.wave, e.id.split(':').pop()) ?? demonEssenceXp(e.rank, e.role)
          s.rawKillXp += xp
          if (!s.training) {
            this._gainXp(xp)
            if (coreDrops) {
              s.earned.cores += CORE_RANK_VALUES[kill.coreRank]
              if (kill.coreRank && !s.pickups) s.drops.push({
                id: this._id('c'), kind: 'core', rank: kill.coreRank, killId: e.id,
                x: e.x, y: e.y, radius: 10 + kill.coreRank, amount: CORE_RANK_VALUES[kill.coreRank],
                expiresAt: s.time + 2,
              })
            } else if (e.role === 'normal') {
              s.normalCoreCounter++
              if (s.normalCoreCounter === 20) { s.earned.cores++; s.normalCoreCounter = 0 }
            } else s.earned.cores += (e.role === 'elite' ? ELITE_CORE : BOSS_CORE)[e.rank]
          }
          if (s.pickups) spawnPickups(this,e)
          s.zones = s.zones.filter(z => z.ownerId !== e.id)
          s.drops.push({ id: this._id('d'), kind: 'resource', x: e.x, y: e.y, radius: 5,
            amount: xp, expiresAt: s.time + .5 })
          // Initial playtest parameter, not a new currency or inventory item.
          // Chance is independent of pickup-radius passives and entirely seeded.
          if (this._random() < .08) s.drops.push({ id: this._id('h'), kind: 'heal',
            x: e.x, y: e.y, radius: 9, amount: s.player.maxHp * .1, expiresAt: s.time + 45 })
        }
        if (s.loadout.growthVersion!==1 && pass === 0 && e.killedBy !== 'gate' && s.time >= s.gateReadyAt && s.gateEntries.length) {
          const targets = this._targets(e, this._passive('sj_gate', 'radius'), 4)
          if (targets.length) {
            let budget = Math.min(s.gateEntries.reduce((sum, b) => sum + b.amount, 0),
              this._passive('sj_gate', 'proc_damage') * s.player.attack)
            const damage = budget / targets.length
            for (const entry of s.gateEntries) {
              const consumed = Math.min(entry.amount, budget)
              entry.amount -= consumed; budget -= consumed
            }
            s.gateEntries = s.gateEntries.filter(b => b.amount > EPS)
            s.gateReadyAt = s.time + 3
            targets.forEach(target => this._damageEnemy({ target: target.id, damage,
              direct: false, scaled: true, source: 'gate' }))
            this._effect('gate', e.x, e.y, this._passive('sj_gate', 'radius'))
          }
        }
      }
    }
  }
  _drops() {
    const s = this.state
    if (s.player.hp <= 0) return
    tickPickups(this, STEP, this._passive(s.loadout.growthVersion === 1 ? 'sj_spirit' : 'magnet', 'pickup_bonus'))
    const pickup = 36 * (1 + this._passive(s.loadout.growthVersion === 1 ? 'sj_spirit' : 'magnet', 'pickup_bonus'))
    s.drops = s.drops.filter(d => {
      if (d.expiresAt <= s.time) return false
      if (d.kind === 'heal' && distance(d, s.player) <= pickup + d.radius) {
        const beforeHp = s.player.hp
        s.player.hp = Math.min(s.player.maxHp, s.player.hp + d.amount)
        if ((s.loadout.passive?.sj_spirit || 0) > 0 && d.amount > 0)
          this._effect('heal_pickup', s.player.x, s.player.y, 0, {
            amount: s.player.hp - beforeHp, collectedAmount: d.amount, dropId: d.id })
        return false
      }
      return true
    })
  }

  _visible(e) {
    const view = this.state.view
    return !view || [e, this.state.player].every(a => a.x - a.radius >= view.xmin
      && a.x + a.radius <= view.xmax && a.y - a.radius >= view.ymin && a.y + a.radius <= view.ymax)
  }
  _attackSpec(e) {
    let base=this._baseAttackSpec(e)
    // 83号：普通怪技能低频，且同屏最多一只普通怪在放技能；被占用时退回普通攻击。
    if (base && isNormalSkill(e, base) && this.state.enemies.some(a => a !== e && a.hp > 0
      && a.role === 'normal' && a.ai.mode !== 'approach' && a.ai.mode !== 'recovery' && a.ai.attack && isNormalSkill(a, a.ai.attack))) {
      base = this._baseAttackSpec(e, true)
    }
    // Give early normal enemies longer gaps after recovery, tapering to the
    // standard cadence at floor four. Includes the floor-one spider tutorial.
    const cooldownScale = e.role === 'normal' ? ([2.5, 2, 1.5][this.state.floor - 1] ?? 1) : 1
    if(base) {
      const ordinary=base.kind!=='charge'
      base={...base,cooldown:isNormalSkill(e, base) ? normalSkillCooldown(this.state.floor)
        : ordinary ? e.attackInterval : base.cooldown*cooldownScale}
    }
    return monsterAttackSpec(this,e,base)
  }
  _baseAttackSpec(e, skillBlocked = false) {
    const s = this.state, d = distance(e, s.player), ai = e.ai
    if(s.arenaVersion === 1 && !pillarSight(e,s.player))return null
    if (s.floor === 1 && e.role === 'boss') {
      const authored = FLOOR01_BOSS.attacks.find(a => d >= a.select_distance_min && d <= a.select_distance_max
        && (ai.cooldowns[a.id] ?? 0) <= s.time)
      if (!authored) return null
      return { kind: authored.id, shape: authored.shape, windup: authored.windup_s,
        active: authored.active_s, recovery: authored.recovery_s, cooldown: authored.cooldown_s,
        range: authored.range, radius: authored.radius ?? authored.width / 2,
        width: authored.width ?? 0, angle: authored.angle_deg ?? 0, damage: authored.damage,
        lock: authored.target_lock_s, speed: authored.dash_speed ?? 0, cost: 2,
        segments: authored.id === 'charge' && ai.phase === 2 ? 2 : 1 }
    }
    if (s.floor === 1 && e.family === 'spider') {
      if (d > e.radius + 54 + 18 || (ai.cooldowns.bite ?? 0) > s.time) return null
      const elite = e.role !== 'normal'
      return { kind: 'bite', shape: 'sector', windup: .65, active: .12, recovery: .6,
        cooldown: elite ? 1.8 : 1.2, range: e.radius + 54, radius: e.radius + 54,
        width: 0, angle: 100, damage: e.damage, lock: .15, speed: 0,
        cost: elite ? 2 : 1, segments: 1 }
    }
    const spec = enemyAttackSpec(e, d, s.time, ai.cooldowns, { skillBlocked })
    const heavy = spec && (spec.kind === 'charge'
      || (spec.kind === 'slam' && ['bear', 'ape', 'yak'].includes(e.family))
      || (spec.kind === 'sweep' && ['tiger', 'crocodile', 'rhino'].includes(e.family)))
    if (e.role === 'boss' && heavy) {
      spec.damage = FLOORS[s.floor - 1].floor_stat_scale.boss_heavy_damage
    }
    return spec
  }
  _newAttack(e, spec, segment = 1) {
    const s = this.state, ai = e.ai, dir = facing(s.player.x - e.x, s.player.y - e.y, ai.faceX, ai.faceY)
    ai.sequence++
    ai.attack = { damageType:'physical', ...spec, id: `${e.id}:a${ai.sequence}:s${segment}`, segment,
      dirX: dir.x, dirY: dir.y, x: e.x, y: e.y, targetX: s.player.x, targetY: s.player.y,
      ...(spec.kind==='shot'?{emissionFaceX:(Math.abs(dir.x)>.01?dir.x:ai.faceX)<0?-1:1}:{}),
      startedAt: s.time, locked: false, hit: false, fired: false, travelled: 0, boundary: false,
      maxRange: spec.maxRange ?? spec.range, clipped: false }
    ai.mode = 'windup'
    ai.until = s.time + spec.windup
    ai.eligibleSince = -1
    this._clipAttack(e)
    this._telegraph(e)
  }
  _clipAttack(e) {
    const a = e.ai.attack
    if (a.kind !== 'charge') return
    a.range = clippedRay(a, a.dirX, a.dirY, a.maxRange, e.radius, this.state.arenaVersion)
    a.clipped = a.range + EPS < a.maxRange
  }
  _telegraph(e) {
    const s = this.state, a = e.ai.attack
    let z = s.zones.find(z => z.ownerId === e.id && z.renderOnly)
    if (!z) {
      z = { id: this._id('warning'), ownerId: e.id, hostile: true, renderOnly: true }
      s.zones.push(z)
    }
    const circleTarget = a.kind === 'stone' || a.kind === 'web'
    Object.assign(z, { kind: e.ai.mode === 'windup' ? 'enemy_windup' : 'enemy_attack',
      phase: e.ai.mode, shape: a.shape, attackId: a.id, x: circleTarget ? a.targetX : a.x,
      y: circleTarget ? a.targetY : a.y, radius: a.radius, width: a.width,
      toX: a.x + a.dirX * a.range, toY: a.y + a.dirY * a.range,
      angle: a.angle, faceX: a.dirX, faceY: a.dirY, locked: a.locked,
      expiresAt: s.time + 1 })
  }
  _recover(e, recovery) {
    e.ai.mode = 'recovery'
    e.ai.until = this.state.time + recovery
    this.state.zones = this.state.zones.filter(z => !(z.ownerId === e.id && z.renderOnly))
  }
  _enemyActions(incoming, oldPlayer) {
    const s = this.state
    for (const e of s.enemies) {
      const ai = e.ai
      if (e.hp <= 0 || monsterMechanicsBlocks(this, e)) continue
      const moveSpeed = e.moveSpeed * monsterMovementMultiplier(this, e)
        * formationMovementMultiplier(s.zones, e, s.time, s.arenaVersion === 1 ? pillarSight : undefined)
      if (ai.mode === 'approach') {
        if (s.time < ai.entryUntil || s.time < ai.transitionUntil || ai.transitionPending) continue
        const d = distance(e, s.player)
        const dir = facing(s.player.x - e.x, s.player.y - e.y, ai.faceX, ai.faceY)
        ai.faceX = dir.x; ai.faceY = dir.y
        const spec = this._attackSpec(e)
        const visible = this._visible(e), style = enemyCombatStyle(e)
        // 83号：远程普通怪在技能冷却期间贴近用普通攻击，技能就绪时再拉开。
        const kiting = style.ranged && (e.role !== 'normal' || (ai.cooldowns.shot ?? 0) <= s.time)
        if (kiting && !(s.floor === 1 && e.family === 'spider') && visible
          && (s.arenaVersion !== 1 || pillarSight(e,s.player))) {
          // Spacing remains active while a shot is cooling. Cap the step at the
          // band edge so fast actors do not oscillate across it.
          let gap = d < style.preferredMin ? d - style.preferredMin : Math.max(0, d - style.preferredMax)
          // 2026-11-13 user report: a spider backing away at full speed, with the blocked player glued to it,
          // moved in lockstep. Spiders back off at 55% speed and hold their ground once in body contact.
          const spider = e.family === 'spider'
          if (spider && gap < 0 && d <= standingDistance(e, s.player) + 6) gap = 0
          const pace = spider && gap < 0 ? SPIDER_RETREAT_PACE : 1
          const travel = Math.min(Math.abs(gap), moveSpeed * pace * STEP), sign = Math.sign(gap)
          const old = { x: e.x, y: e.y }
          e.x += dir.x * travel * sign; e.y += dir.y * travel * sign
          boundActor(e, s.arenaVersion)
          if (gap < 0 && distance(old, e) < travel * .25) {
            // A wall can block retreat. Try both tangents in a stable order,
            // keeping only a legal step that increases distance from the player.
            for (const side of [ai.orbitSign, -ai.orbitSign]) {
              const candidate = { x: old.x - dir.y * travel * side,
                y: old.y + dir.x * travel * side, radius: e.radius }
              boundActor(candidate, s.arenaVersion)
              if (distance(candidate, s.player) > distance(e, s.player) + EPS) {
                e.x = candidate.x; e.y = candidate.y
              }
            }
          }
        } else if (!spec || !visible) {
          let dx = dir.x, dy = dir.y
          if (['wolf', 'bat', 'centipede'].includes(e.family) && d > 160) {
            const side = (e.family === 'centipede' ? Math.sin(s.time * 3 + ai.offset) : ai.orbitSign) * .35
            const steer = facing(dx - dy * side, dy + dx * side)
            dx = steer.x; dy = steer.y
          }
          if(s.arenaVersion === 1){const route=steerPillars(e,s.player,e.radius);dx=route.x;dy=route.y}
          e.x += dx * moveSpeed * STEP
          e.y += dy * moveSpeed * STEP
          boundActor(e, s.arenaVersion)
        }
        continue
      }
      const a = ai.attack
      if (!this._visible(e) && ai.mode !== 'recovery') {
        a.segments = a.segment
        this._recover(e, .6)
        continue
      }
      if (ai.mode === 'windup') {
        if (!a.locked) {
          const dir = facing(s.player.x - e.x, s.player.y - e.y, a.dirX, a.dirY)
          a.dirX = dir.x; a.dirY = dir.y
          a.targetX = s.player.x; a.targetY = s.player.y
          this._clipAttack(e)
          if (s.time + EPS >= a.startedAt + a.lock) {
            a.locked = true
            if (s.floor === 1 && e.role === 'boss' && a.kind === 'charge'
              && (a.range < 120 || a.segment > 1 && distance(e, s.player) < 60)) {
              a.segments = a.segment
              this._recover(e, .6)
              continue
            }
          }
        }
        this._telegraph(e)
        if (s.time + EPS < ai.until) continue
        ai.mode = 'active'; ai.until = s.time + a.active
      }
      if (ai.mode === 'active') {
        if (a.kind === 'charge') {
          const old = { x: e.x, y: e.y }
          const travel = Math.min(a.speed * STEP, a.range - a.travelled)
          e.x += a.dirX * travel; e.y += a.dirY * travel
          const unclipped = { x: e.x, y: e.y }
          boundActor(e, s.arenaVersion)
          a.travelled += distance(old, e)
          a.boundary = distance(unclipped, e) > EPS || a.clipped && a.travelled >= a.range - EPS
          const relativeOld = { x: old.x - oldPlayer.x + s.player.x, y: old.y - oldPlayer.y + s.player.y }
          if (!a.hit && segmentDistance(s.player, relativeOld, e) <= e.radius + 18) {
            incoming.push({ id: a.id, damage: a.damage, damageType:a.damageType ?? 'physical' }); a.hit = true
          }
          if (a.boundary || a.travelled >= a.range - EPS) ai.until = s.time
        } else if (['shot', 'stone', 'web'].includes(a.kind)) {
          if (!a.fired) {
            a.fired = true
            if (a.kind === 'shot') {
              const spread = e.role === 'boss' ? [-.25, 0, .25] : [0]
              const launch = {x:e.x,y:e.y,range:distance(e,{x:a.targetX,y:a.targetY}),
                family:A[e.archetype]?.art_family||e.family,role:e.role,rank:e.rank,radius:e.radius,
                faceX:(Math.abs(a.dirX)>.01?a.dirX:a.emissionFaceX??1)<0?-1:1,enraged:!!e.mechanic?.enraged}
              for (const angle of spread) {
                const x = a.dirX * Math.cos(angle) - a.dirY * Math.sin(angle)
                const y = a.dirX * Math.sin(angle) + a.dirY * Math.cos(angle)
                this._projectile(e.x, e.y, x * a.speed, y * a.speed, 12, a.damage, true,
                  { source: a.id, ownerId: e.id, launch:{...launch}, damageType:a.damageType ?? 'physical', ...(a.element === undefined ? {} : { element: a.element }) })
              }
            } else if(s.arenaVersion !== 1 || pillarSight(e,{x:a.targetX,y:a.targetY})) this._zone(a.kind, a.targetX, a.targetY, a.radius, a.damage,
              .35, a.kind === 'web' ? 4 : 1, 1, 1, true, false, { ownerId: e.id, source: a.id, damageType:a.damageType ?? 'physical' })
          }
        } else if (!a.hit && (s.arenaVersion !== 1 || pillarSight(a,s.player)) && (a.shape === 'circle' ? distance(s.player, a) <= a.radius + 18
          : inSector(s.player, a, { x: a.dirX, y: a.dirY }, a.range, a.angle, 18))) {
          incoming.push({ id: a.id, damage: a.damage, damageType:a.damageType ?? 'physical' }); a.hit = true
        }
        this._telegraph(e)
        if (s.time + EPS >= ai.until) {
          const recovery = a.boundary ? 1.2 : a.segment === a.segments && a.segments > 1 ? 1.2 : a.recovery
          if (a.boundary) a.segments = a.segment
          this._recover(e, recovery)
        }
      } else if (ai.mode === 'recovery' && s.time + EPS >= ai.until) {
        if (a.segment < a.segments && distance(e, s.player) >= 60 && this._visible(e)) {
          this._newAttack(e, a, a.segment + 1)
        } else {
          ai.cooldowns[a.kind] = s.time + a.cooldown
          // 83号：普通怪的普通攻击与技能共用一个出招节奏，技能替换一次普通攻击，不额外加招。
          if (e.role === 'normal') for (const kind of ['bite', normalSkillKind(e.family)].filter(Boolean)) {
            ai.cooldowns[kind] = Math.max(ai.cooldowns[kind] ?? 0, s.time + e.attackInterval)
          }
          ai.readyAt = s.time
          ai.mode = 'approach'; ai.attack = null
        }
      }
    }
  }
  _requestAttacks(drainMonsterProjectiles = false) {
    const s = this.state
    if (drainMonsterProjectiles) return
    // Existing windups finish normally; new native attacks wait until the
    // mechanic and its recovery window have ended, preventing CC followups.
    if (s.monsterMechanics && s.enemies.some(e => e.hp > 0
      && e.mechanic && e.mechanic.phase !== 'idle')) return
    const boss = !s.monsterMechanics && s.floor === 1 ? s.enemies.find(e => e.role === 'boss') : null
    if (boss && boss.ai.phase === 1 && boss.hp <= boss.maxHp / 2) boss.ai.transitionPending = true
    if (boss && s.time < boss.ai.entryUntil) return
    if (boss && boss.ai.transitionPending) {
      if (boss.ai.mode === 'windup') {
        boss.ai.attack.segments = boss.ai.attack.segment
        this._recover(boss, .6)
      }
      if (!s.enemies.some(e => e.ai.mode !== 'approach') && !boss.ai.transitionUntil) {
        boss.ai.transitionUntil = s.time + 1.2
      }
      if (boss.ai.transitionUntil && s.time >= boss.ai.transitionUntil) {
        boss.ai.transitionPending = false; boss.ai.phase = 2
      } else return
    }
    if (boss && s.time < boss.ai.entryUntil || s.time < s.nextWindupAt) return
    const budget = s.floor === 1 ? 2 : 3 + Math.floor(s.floor / 3)
    const spent = s.enemies.reduce((sum, e) => sum + (e.ai.mode !== 'approach' ? e.ai.attack.cost : 0), 0)
    const eligible = []
    for (const e of s.enemies) {
      if (monsterMechanicsBlocks(this, e)) continue
      const ai = e.ai, spec = this._attackSpec(e)
      if (ai.mode !== 'approach' || s.time < ai.readyAt || s.time < ai.graceUntil
        || s.time < ai.entryUntil || !spec || !this._visible(e)) { ai.eligibleSince = -1; continue }
      if (ai.eligibleSince < 0) ai.eligibleSince = s.time
      eligible.push({ e, spec })
    }
    eligible.sort((a, b) => a.e.ai.eligibleSince - b.e.ai.eligibleSince || a.e.id.localeCompare(b.e.id))
    if (eligible.length && eligible[0].spec.cost + spent <= budget) {
      this._newAttack(eligible[0].e, eligible[0].spec)
      s.nextWindupAt = s.time + .25
    }
  }
}
